local config = {
  ui_story_5085_50850100_1_dialog_content = "Urgh, mi cabeza...",
  ui_story_5085_50850100_2_dialog_content = "Se siente como... si hubiera tragado un montón de agua de mar...",
  ui_story_5085_50850100_3_dialog_content = "<color=#e8d9bb>Fwoosh, Fwoosh—</color>",
  ui_story_5085_50850100_4_dialog_content = "¡Uf, estoy tan harto del sonido de las olas... Espera, ¿realmente estoy en la playa?",
