  ui_story_5085_50850100_10_dialog_content = "¿Eh...? ¡T-Tú no eres Vice!",
  ui_story_5085_50850100_11_dialog_content = "Lo siento, pensé que eras otra persona! No espera... Debería agradecerte por salvarme la vida...",
