  ui_story_5085_50850100_14_dialog_content = "Juzgando por tu situación, no parece que estemos en el mundo de Oren ya. Esto podría ser un problema...",
  ui_story_5085_50850100_15_dialog_content = "¿Qué es el Oren? Espera... ¿Dijiste \"nuevo mundo\"?!",
  ui_story_5085_50850100_16_dialog_content = "¡Así es!",
  ui_story_5085_50850100_17_dialog_content = "Mis amigos y yo estábamos investigando formas de viajar al inframundo...",
  ui_story_5085_50850100_18_dialog_content = "¡Pero luego algo salió mal con el portal, y terminamos aquí dentro!",
  ui_story_5085_50850100_19_dialog_content = "¡Incluso con toda mi experiencia en aventuras, no tengo idea de cómo proceder! Entonces, amigo—",
  ui_story_5085_50850100_20_dialog_content = "¿Te importaría presentarme este mundo?",
  ui_story_5085_50850100_21_dialog_content = "¿Presentar... el mundo...?",
  ui_story_5085_50850100_22_dialog_content = "<color=#e8d9bb>Graznar—Graznar—</color>",
  ui_story_5085_50850100_23_dialog_content = "... Y eso es más o menos la historia de Astra.",
  ui_story_5085_50850100_24_dialog_content = "Pero no creo que estemos en el continente principal ya. Si acaso, esto parece una isla frente a la costa de Astra.",
  ui_story_5085_50850100_25_dialog_content = "PlayerName! ¡La Unión de Mensajeros acaba de enviarnos las últimas noticias sobre algunas ruinas que encontraron en una isla!",
  ui_story_5085_50850100_26_dialog_content = "¿Oh? ¿Te refieres a las ruinas de la isla de las que todos han estado hablando últimamente?",
  ui_story_5085_50850100_27_dialog_content = "¡Así es! Aparentemente, pertenecen a un antiguo reino auroriano que rara vez aparece en los registros históricos.",
  ui_story_5085_50850100_28_dialog_content = "¡Algunos académicos piensan que este reino puede llenar el vacío que apareció después de que los Aurorianos abandonaron Northland!",
  ui_story_5085_50850100_29_dialog_content = "¡Lumopolis y Umbraton ya se están preparando para investigar la isla, y están ofreciendo comisiones masivas para cualquiera que ayude con sus exploraciones!",
  ui_story_5085_50850100_30_dialog_content = "¿D-Dijiste \"comisiones enormes\"?!",
  ui_story_5085_50850100_31_dialog_content = "Nosotros... No es demasiado tarde para registrarnos, ¿verdad?!",
  ui_story_5085_50850100_32_dialog_content = "Jeje, ¡sabía que te interesaría!",
  ui_story_5085_50850100_33_dialog_content = "Y no te preocupes por los gastos de viaje. Ya hablé con algunos que también van en esa dirección.",
  ui_story_5085_50850100_34_dialog_content = "¡Todos han acordado reunirse e ir juntos para reducir los costos de viaje!",
  ui_story_5085_50850100_35_dialog_content = "Solo necesito que verifiques con ellos los detalles del viaje antes de que nos vayamos.",
  ui_story_5085_50850100_36_dialog_content = "Eres muy minucioso... Muy bien, ¡iré a hacer la revisión final ahora!",
  ui_story_5085_50850100_37_dialog_content = "¡PlayerName! ¡Quiero ir a la isla y buscar música del antiguo reino!",
  ui_story_5085_50850100_38_dialog_content = "¡Estoy seguro de que hará que mis actuaciones de Rediesel ardan más que nunca antes! ¡Solo tienes que llevarme contigo!",
  ui_story_5085_50850100_39_dialog_content = "¡Claro, no hay problema!",
  ui_story_5085_50850100_40_dialog_content = "Hay rumores de antiguos mechs en las ruinas. Mi curiosidad estaba superándome. Tenía que verlo por mí mismo.",
  ui_story_5085_50850100_41_dialog_content = "Por favor, PlayerName!",
  ui_story_5085_50850100_42_dialog_content = "¡No hay objeciones aquí!",
  ui_story_5085_50850100_43_dialog_content = "¡D-Déjame una cosa clara! No voy porque quiera pasar tiempo en la playa este verano...",
  ui_story_5085_50850100_44_dialog_content = "Acabo de ver lo duro que Vice estaba trabajando para prepararse para este viaje... No quiero que se exceda, así que pensé que debería acompañarla.",
  ui_story_5085_50850100_45_dialog_content = "Por supuesto, ¡muy apreciado, Zarya!",
  ui_story_5085_50850100_46_dialog_content = "<color=#e8d9bb>Con un equipo de cinco ya elegido, la fiesta parte para una emocionante aventura en la isla...</color>",
  ui_story_5085_50850100_47_dialog_content = "¿Todos aquí? ¡Bien! Ahora vamos hacia nuestro destino—",
  ui_story_5085_50850100_48_dialog_content = "¡A las ruinas de la isla!",
  ui_story_5085_50850100_49_dialog_content = "¡Espero que descubramos algunos instrumentos musicales antiguos!",
  ui_story_5085_50850100_50_dialog_content = "¡O algunos mechas antiguos legendarios!",
  ui_story_5085_50850100_51_dialog_content = "Esta isla seguro guarda muchos misterios.",
  ui_story_5085_50850100_52_dialog_content = "(Vice y los demás... todos parecen un poco demasiado optimistas sobre este viaje.)",
  ui_story_5085_50850100_53_dialog_content = "(La gente suele volver de este tipo de aventuras con las manos vacías... Pero tal vez solo estoy siendo demasiado negativo.)",
  ui_story_5085_50850100_54_dialog_content = "PlayerName, ¡el Sr. Corax está llamando!",
  ui_story_5085_50850100_55_dialog_content = "Escuché que estás en camino a las ruinas de la isla. ¿Es eso correcto?",
  ui_story_5085_50850100_56_dialog_content = "Realmente quería que te unieras a mí en esta expedición y buscaras cualquier conocimiento médico Auroriano perdido, pero parece que llegué demasiado tarde.",
  ui_story_5085_50850100_57_dialog_content = "¿Incluso tú también?!",
  ui_story_5085_50850100_58_dialog_content = "Lo siento... Muchas personas han estado preguntando por razones similares.",
  ui_story_5085_50850100_59_dialog_content = "Explorar ruinas nunca es un asunto sencillo. Esperemos que el equipo que has formado incluya luchadores y médicos capaces.",
  ui_story_5085_50850100_60_dialog_content = "Por lo que he oído, el clima extremo por sí solo ha derrotado a muchos equipos de exploración. Me preocupo por tu bienestar.",
  ui_story_5085_50850100_61_dialog_content = "Creo que estaremos bien...",
  ui_story_5085_50850100_62_dialog_content = "El mar ha estado tranquilo todo este tiempo...",
  ui_story_5085_50850100_63_dialog_content = "¿¡Qué es esto?! ¿¡Rayo... en un día despejado?!",
  ui_story_5085_50850100_64_dialog_content = "¡Ahhhh—Está lloviendo fuego! ¡Pónganse a cubierto, todos!",
  ui_story_5085_50850100_65_dialog_content = "¿El-El barco no va a volcar, verdad?!",
  ui_story_5085_50850100_66_dialog_content = "¡Esperen, todos!",
  ui_story_5085_50850100_67_dialog_content = "<size=50><color=#e8d9bb>Auge—!</color></size>",
  ui_story_5085_50850100_68_dialog_content = "<color=#e8d9bb>El barco se está despedazando, y la tripulación se aferra desesperadamente a los restos, zarandeados por las olas despiadadas.</color>",
  ui_story_5085_50850100_69_dialog_content = "<color=#e8d9bb>A la deriva en las corrientes, me encontré aquí antes de darme cuenta...</color>",
  ui_story_5085_50850100_70_dialog_content = "Entonces... Yo tampoco estoy muy familiarizado con este lugar. Lo siento.",
  ui_story_5085_50850100_71_dialog_content = "No estoy del todo seguro de que pueda ayudarte de alguna manera, tampoco...",
  ui_story_5085_50850100_72_dialog_content = "Veo. ¡Está bien!",
  ui_story_5085_50850100_73_dialog_content = "¡Gracias por la información! Ahora siento que tengo una buena comprensión de esta situación.",
  ui_story_5085_50850100_74_dialog_content = "Cuando se trata de lugares como islas y ruinas, ¡tengo mucha experiencia!",
  ui_story_5085_50850100_75_dialog_content = "¡Eso es un alivio! Antes de venir aquí, tenía una buena idea de qué esperar.",
  ui_story_5085_50850100_76_dialog_content = "Solo me pregunto dónde terminaron los demás. También deben haber llegado a la orilla, ¿verdad?",
  ui_story_5085_50850100_77_dialog_content = "Tus amigos... ¡Ay, eso me recuerda!",
  ui_story_5085_50850100_78_dialog_content = "Klaudia y Patty también fueron enviados a este mundo, pero no he podido encontrar a ninguno de ellos...",
  ui_story_5085_50850100_79_dialog_content = "¡Pero algo me dice que definitivamente están en esta isla!",
  ui_story_5085_50850100_80_dialog_content = "Y si me perdonas la expresión, parece que tú y yo estamos en el mismo barco aquí.",
  ui_story_5085_50850100_81_dialog_content = "Jaja, puedes decir eso de nuevo...",
  ui_story_5085_50850100_82_dialog_content = "Y ya que ese es el caso... ¿Por qué no intentamos buscar a nuestros amigos juntos?",
  ui_story_5085_50850100_83_dialog_content = "¡Seremos mucho más efectivos si trabajamos en equipo!",
  ui_story_5085_50850100_84_dialog_content = "¿¡En serio?! Oh, ¡muchas gracias por tu ayuda! Sabes, pareces bastante preocupado por tus amigos también. Seguías llamando a \"Vice\" cuando estabas inconsciente antes...",
  ui_story_5085_50850100_85_dialog_content = "Debe ser tu amiga más cercana, ¿eh?",
  ui_story_5085_50850100_86_dialog_content = "¡¿E-Es eso lo que piensas?!",
  ui_story_5085_50850100_87_dialog_content = "... Tal vez tengas razón. Venir aquí fue su idea, y ni siquiera dudé en unirme a ella.",
  ui_story_5085_50850100_88_dialog_content = "¡Oh, ya veo! Ella debe amar las aventuras. ¡Estoy aún más emocionado de conocerla ahora!",
  ui_story_5085_50850100_89_dialog_content = "¿Puedes caminar? Puedes apoyarte en mí si estás herido.",
  ui_story_5085_50850100_90_dialog_content = "Gracias, pero creo que puedo arreglármelas.",
  ui_story_5085_50850100_91_dialog_content = "¡Bien! Entonces, permítame presentarme formalmente—",
  ui_story_5085_50850100_92_dialog_content = "Mi nombre es Reisalin Stout, pero puedes llamarme simplemente Ryza!",
  ui_story_5085_50850100_93_dialog_content = "Encantado de conocerte, Ryza. Mi nombre es PlayerName, pero la mayoría de las personas simplemente me llaman el Navegador.",
  ui_story_5085_50850100_94_dialog_content = "¡Suena bien! ¡Espero con ansias trabajar contigo, Navegador!",
  ui_story_5085_50850100_95_dialog_content = "¡Ahora vamos!",
  ui_story_5085_50850201_1_dialog_content = "Uf... Esto parece bastante útil.",
  ui_story_5085_50850201_2_dialog_content = "¡Guau, esta flor es hermosa! Me pregunto si puedo usarla como sustituto de las Flores de Salud.",
  ui_story_5085_50850201_3_dialog_content = "¿Crees que esta roca tiene algún uso? Debería llevarla conmigo, solo para estar seguro...",
  ui_story_5085_50850201_4_dialog_content = "Uh, parece que tu paquete ya está bastante lleno.",
  ui_story_5085_50850201_5_dialog_content = "¡Ah! Tienes razón, probablemente me dejé llevar un poco con mi recolección...",
  ui_story_5085_50850201_6_dialog_content = "Pareces bastante aficionado a las plantas, especialmente... ¿raíces de hierba?",
  ui_story_5085_50850201_7_dialog_content = "Eheheh... No exactamente. ¡Solo quiero intentar usar estos como materiales de <color=#FFB400>alquimia</color>!",
  ui_story_5085_50850201_8_dialog_content = "¿A-Alquimia?!",
  ui_story_5085_50850201_9_dialog_content = "¿Eh? ¿La alquimia no existe en este mundo o algo así?",
  ui_story_5085_50850201_10_dialog_content = "Emmm, en lo que respecta al mundo, es más un arte perdido del antiguo pasado.",
  ui_story_5085_50850201_11_dialog_content = "Entonces, ¿realmente existe en tu mundo?",
  ui_story_5085_50850201_12_dialog_content = "¡Así es! Y no me subestimes, en realidad soy un <color=#FFB400>alquimista</color> bastante logrado.",
  ui_story_5085_50850201_13_dialog_content = "¡Puedo usar todo tipo de objetos regulares como materiales y <color=#FFB400>sintetizar</color>los en medicinas y otros artículos útiles!",
  ui_story_5085_50850201_14_dialog_content = "¿En serio? ¡Eso es impresionante!",
  ui_story_5085_50850201_15_dialog_content = "Si tan solo tuviera un buen y grande caldero de alquimia... ¡Entonces podría mostrarte lo que realmente puedo hacer!",
  ui_story_5085_50850201_16_dialog_content = "¿Un caldero, eh? No estoy seguro de que encontraremos algo así en una isla desierta... Pero tal vez las ruinas tengan algo que puedas usar?",
  ui_story_5085_50850201_17_dialog_content = "En cualquier caso, sigamos adelante. Incluso podríamos encontrar cosas mejores más adelante.",
  ui_story_5085_50850201_18_dialog_content = "¡Ahora estás hablando mi idioma!",
  ui_story_5085_50850201_19_dialog_content = "Permíteme aligerar un poco mi carga primero.",
  ui_story_5085_50850201_20_dialog_content = "También puedo ayudarte a llevar algunas cosas. Después de todo, dudo que vayamos a dejar esta isla pronto.",
  ui_story_5085_50850201_21_dialog_content = "Si vamos a estar atrapados aquí durante unos días, ¡estoy seguro de que tu alquimia definitivamente será útil!",
  ui_story_5085_50850201_22_dialog_content = "¡Tienes un punto!",
  ui_story_5085_50850201_23_dialog_content = "Entonces empezaremos buscando a nuestros amigos, luego buscaremos el caldero...",
  ui_story_5085_50850201_24_dialog_content = "Graah—",
  ui_story_5085_50850201_25_dialog_content = "¡Ah! ¡E-Es un monstruo!",
  ui_story_5085_50850201_26_dialog_content = "¿Son todos los monstruos en tu mundo tan aterradores?!",
  ui_story_5085_50850201_27_dialog_content = "¿¡Hay Eclipsites incluso en una isla remota como esta!?",
  ui_story_5085_50850201_28_dialog_content = "Esto es malo... sin Aurorianos alrededor...",
  ui_story_5085_50850201_29_dialog_content = "¿Eclipsitos? ¿Es eso como llamas a estas cosas?",
  ui_story_5085_50850201_30_dialog_content = "Ese parece que lleva algo en sus garras...",
  ui_story_5085_50850201_31_dialog_content = "Un minuto, ¿no es eso...?",
  ui_story_5085_50850201_32_dialog_content = "¿¡El paquete de Vice!?",
  ui_story_5085_50850201_33_dialog_content = "<color=#e8d9bb>¡Golpear!</color>",
  ui_story_5085_50850201_34_dialog_content = "¡Eclipsite podrido! Devuélveme mi... ¡Ah! PlayerName!",
  ui_story_5085_50850201_35_dialog_content = "¡Perfecto momento! ¡Nuestros suministros aún están en ese paquete! ¡Estaremos en problemas si no lo recuperamos!",
  ui_story_5085_50850201_36_dialog_content = "¡Dame una mano!",
  ui_story_5085_50850201_37_dialog_content = "¡Entendido!",
  ui_story_5085_50850202_1_dialog_content = "Uf, eso se encarga de eso!",
  ui_story_5085_50850202_2_dialog_content = "Habríamos tenido que sobrevivir como cavernícolas sin estos suministros.",
  ui_story_5085_50850202_3_dialog_content = "¡Estoy tan contento de haberte encontrado, PlayerName! Pero eh, ¿quién es este...?",
  ui_story_5085_50850202_4_dialog_content = "¡Ah, debes ser Vice! El Navegante me habló de ti cuando nos conocimos por primera vez. ¡Mi nombre es Ryza!",
  ui_story_5085_50850202_5_dialog_content = "Eh—Sí, me llamo Vice; encantado de conocerte, señorita Ryza! Eh... ¿También eres una aventurera explorando la isla?",
  ui_story_5085_50850202_6_dialog_content = "Más o menos... Para ser más específico, ella es una alquimista que vino aquí desde otro mundo.",
  ui_story_5085_50850202_7_dialog_content = "¿Un alquimista... de otro mundo?",
  ui_story_5085_50850202_8_option_content = "Explica la situación a Vice",
  ui_story_5085_50850202_9_dialog_content = "<color=#e8d9bb>Le doy a Vice un resumen rápido de cómo Ryza y yo nos conocimos.</color>",
  ui_story_5085_50850202_10_dialog_content = "Así que eso fue lo que pasó, ¿eh?",
  ui_story_5085_50850202_11_dialog_content = "¡Sí! ¡También seguía llamándote por tu nombre cuando aún estaba inconsciente!",
  ui_story_5085_50850202_12_dialog_content = "Entiendo...",
  ui_story_5085_50850202_13_dialog_content = "E-Ejem... Creo que deberíamos pasar a algo más importante, como nuestra situación actual.",
  ui_story_5085_50850202_14_dialog_content = "Estoy de acuerdo.",
  ui_story_5085_50850202_15_dialog_content = "Cuando estaba persiguiendo a ese Eclipsite, me di cuenta de que había muchos más Eclipsites en esta isla de lo que pensaba.",
  ui_story_5085_50850202_16_dialog_content = "Los recursos también son especialmente escasos. Si no podemos encontrar una forma de reponer nuestros suministros...",
  ui_story_5085_50850202_17_dialog_content = "Solo un segundo, Vice! Estás herido, ¿no?",
  ui_story_5085_50850202_18_dialog_content = "Si no te importa, intenta aplicar un poco de esta medicina a tu herida. La hice usando alquimia.",
  ui_story_5085_50850202_19_dialog_content = "¿Eh? Está bien, es solo un rasguño... Preferiría no desperdiciar tu preciosa medicina en algo como esto...",
  ui_story_5085_50850202_20_dialog_content = "Está bien, de verdad—",
  ui_story_5085_50850202_21_dialog_content = "<color=#e8d9bb>Ryza extendió suavemente algo de su medicina en la herida de Vice—</color>",
  ui_story_5085_50850202_22_dialog_content = "Nngh... ¡¿Eh?!",
  ui_story_5085_50850202_23_dialog_content = "Está completamente curado... ¿Es este el poder de tu alquimia, Ryza?",
  ui_story_5085_50850202_24_dialog_content = "¡Debes poder hacer cualquier cosa con él!",
  ui_story_5085_50850202_25_dialog_content = "¡Así es! ¡La alquimia puede resolver casi cualquier problema! O al menos me gusta pensar así... Pero estoy seguro de que hará la vida en esta isla remota mucho más fácil! ¡Incluso podría ser útil contra los Eclipsites!",
  ui_story_5085_50850202_26_dialog_content = "¡Estoy seguro de que puede! Creo en tu fuerza.",
  ui_story_5085_50850202_27_dialog_content = "¡Apuesto a que Vice también lo ve! Serías el compañero perfecto para explorar ruinas antiguas y territorios secretos.",
  ui_story_5085_50850202_28_dialog_content = "¡Estoy de acuerdo! Nada es mejor que cruzarse con un aliado poderoso como tú.",
  ui_story_5085_50850202_29_dialog_content = "Jaja, supongo que también debería trabajar duro por el bien de todos. Y comenzaré buscando el caldero.",
  ui_story_5085_50850202_30_dialog_content = "¿Un caldero?",
  ui_story_5085_50850202_31_dialog_content = "Es lo que Ryza necesita para realizar alquimia y crear todo tipo de objetos. Cualquier cosa que se parezca a una olla servirá.",
  ui_story_5085_50850202_32_dialog_content = "Lo tengo.",
  ui_story_5085_50850202_33_dialog_content = "Vi algo así en mi camino aquí. Parecía algún tipo de recipiente ceremonial en las ruinas...",
  ui_story_5085_50850202_34_dialog_content = "<color=#e8d9bb>El sonido de una flauta surge repentinamente desde lo profundo del bosque—</color>",
  ui_story_5085_50850202_35_dialog_content = "¡Creo que hay alguien en el bosque!",
  ui_story_5085_50850202_36_dialog_content = "Ese instrumento... ¡Debe ser Klaudia!",
  ui_story_5085_50850202_37_dialog_content = "¡Por favor, ven conmigo! Ella es mi compañera más confiable... ¡Así como mi mejor amiga!",
  ui_story_5085_50850301_1_dialog_content = "¡Ven, mi amigo de una tierra lejana! ¡Vamos a derrotar a los Eclipsites en mano!♪",
  ui_story_5085_50850301_2_dialog_content = "Ah, es PlayerName!",
  ui_story_5085_50850301_3_dialog_content = "¡Gracias a Dios que todavía estás vivo!",
  ui_story_5085_50850301_4_dialog_content = "¡Lo siento, pero no caigo tan fácilmente!",
  ui_story_5085_50850301_5_dialog_content = "Klaudia!",
  ui_story_5085_50850301_6_dialog_content = "¡Ah, Ryza!",
  ui_story_5085_50850301_7_dialog_content = "Gracias a Dios... Cuando todos se separaron en el portal, no sabía qué hacer...",
  ui_story_5085_50850301_8_dialog_content = "Lo siento por hacerte preocupar, Klaudia.",
  ui_story_5085_50850301_9_dialog_content = "Pero si pude encontrarte aquí, eso significa que Patty probablemente también esté en algún lugar de la isla.",
  ui_story_5085_50850301_10_dialog_content = "Sí, también lo creo.",
  ui_story_5085_50850301_11_dialog_content = "Sabía que eventualmente me encontrarías, así que decidí quedarme aquí y proteger esto para ti, Ryza.",
  ui_story_5085_50850301_12_dialog_content = "Es...",
  ui_story_5085_50850301_13_dialog_content = "¡Un barril!",
  ui_story_5085_50850301_14_dialog_content = "Uh, no... Me refería a la cosa al lado de eso.",
  ui_story_5085_50850301_15_dialog_content = "¡Oh! Es... Es un gran y hermoso caldero! ¡Muchas gracias, Klaudia!",
  ui_story_5085_50850301_16_dialog_content = "Parece ser una reliquia de una antigua civilización, pero el tamaño y la forma son perfectos para la alquimia.",
  ui_story_5085_50850301_17_dialog_content = "¡Es el recipiente de tres patas que vi antes! Las ruinas deben estar justo por aquí en algún lugar.",
  ui_story_5085_50850301_18_dialog_content = "¡Ah, olvidé presentarnos! Mi nombre es Vice, y este es PlayerName, nuestro Navegante.",
  ui_story_5085_50850301_X18_dialog_content = "Un placer conocerlos, señorita Vice y señor Navegante. La señorita Barbara me habló de ustedes en el camino; ¡Espero que podamos convertirnos en buenos amigos!",
  ui_story_5085_50850301_X19_dialog_content = "¡Estoy seguro de que lo harás! Ahora no desperdiciemos todo el duro trabajo de Klaudia... PlayerName, ¿podrías usar tus poderes para sentir este caldero?",
  ui_story_5085_50850301_19_dialog_content = "Estoy de acuerdo. No queremos que le pase nada a Ryza una vez que empiece a usarlo.",
  ui_story_5085_50850301_20_dialog_content = "¿Qué es eso? ¿El gran y poderoso Navegante finalmente va a usar sus misteriosas habilidades?",
  ui_story_5085_50850301_21_dialog_content = "No es nada, solo la percepción extrasensorial habitual—",
  ui_story_5085_50850301_22_option_content = "¡Potencia de fuerza!",
  ui_story_5085_50850301_23_dialog_content = "...",
  ui_story_5085_50850301_24_dialog_content = "¿Bien?",
  ui_story_5085_50850301_25_dialog_content = "Veo un conjunto de ruinas... con muchos vasos rotos tirados en el suelo...",
  ui_story_5085_50850301_26_dialog_content = "Parece que son parte de las ruinas después de todo.",
  ui_story_5085_50850301_27_dialog_content = "Un pequeño reino insular construido con la tecnología de la antigua civilización, prosperó hasta que...",
  ui_story_5085_50850301_28_dialog_content = "Regresa. El reino te necesita.",
  ui_story_5085_50850301_29_dialog_content = "Ah—",
  ui_story_5085_50850301_30_dialog_content = "¿Qué paso?",
  ui_story_5085_50850301_31_dialog_content = "Pareces que has visto un fantasma. ¿Quieres agua?",
  ui_story_5085_50850301_32_dialog_content = "... No es nada. Acabo de ver la historia de las ruinas, y había mucho que asimilar de una vez...",
  ui_story_5085_50850301_33_dialog_content = "De todos modos, no hay contaminación de Darkflow en el recipiente, y los Eclipsites ni siquiera han tocado. Debería ser seguro usarlo.",
  ui_story_5085_50850301_34_dialog_content = "¿En serio? ¡Genial, muchas gracias! Pero aún así, espero que no estés exagerando con esto.",
  ui_story_5085_50850301_35_dialog_content = "Estoy bien, sinceramente. Además, realmente estoy deseando ver cómo tus poderes mejorarán nuestra vida en la isla desierta!",
  ui_story_5085_50850301_36_dialog_content = "¡No hay necesidad de preocuparse por eso! Conmigo cerca, la supervivencia está a punto de ser mucho más fácil!",
  ui_story_5085_50850301_37_dialog_content = "Pero... Todavía hay un obstáculo muy grande para nuestra supervivencia acechando alrededor...",
  ui_story_5085_50850301_38_dialog_content = "Esas criaturas malvadas se están volviendo terriblemente inquietas. Si no fuera por las increíbles habilidades de lucha de la señorita Barbara justo ahora...",
  ui_story_5085_50850301_39_dialog_content = "Oh vaya, no soy TAN fuerte, sabes.",
  ui_story_5085_50850301_40_dialog_content = "¡Tu apoyo fue la única razón por la que nuestra batalla transcurrió tan sin problemas, amigo mío!",
  ui_story_5085_50850301_41_dialog_content = "Y esa flauta... ¡Era tan cautivadora, incluso para un ídolo profesional como yo!",
  ui_story_5085_50850301_42_dialog_content = "Necesitamos tomar algunas precauciones contra los Eclipsites. Deberíamos establecer un campamento en un lugar que pueda ser defendido fácilmente.",
  ui_story_5085_50850301_43_dialog_content = "Este mundo tuyo... ¿Tiene algún objeto o material para repeler monstruos? Quiero decir, ¿Eclipsites?",
  ui_story_5085_50850301_44_dialog_content = "Lo dudo. Desearía que hubiera algo tan fácil aquí.",
  ui_story_5085_50850301_45_dialog_content = "Em...",
  ui_story_5085_50850301_46_dialog_content = "¿Qué te pasa, Klaudia?",
  ui_story_5085_50850301_47_dialog_content = "Ryza, ¿crees que... podremos volver a casa?",
  ui_story_5085_50850301_48_dialog_content = "Por supuesto. Siempre hemos regresado de nuestras aventuras, ¿no es así?",
  ui_story_5085_50850301_50_dialog_content = "Sé que ya hemos tenido algunos problemas, pero en este momento solo quiero disfrutar de mi aventura con todos aquí!",
  ui_story_5085_50850301_51_dialog_content = "¡De acuerdo! ¡Nada es más divertido que ir de aventuras contigo, Ryza!",
  ui_story_5085_50850301_53_dialog_content = "¡Jejejeje, gracias! Ahora bien, por el bien de encontrar nuestro camino a casa de manera segura, ¡unámonos al Navegante y sus amigos y busquemos a Patty!",
  ui_story_5085_50850301_58_dialog_content = "¡Un momento! Creo que escucho algo espantoso...",
  ui_story_5085_50850301_59_dialog_content = "¡Eclipsitos! ¡Y se están acercando más!",
  ui_story_5085_50850301_60_dialog_content = "Graah—",
  ui_story_5085_50850301_61_dialog_content = "¡Cuidado, Ryza!",
  ui_story_5085_50850301_62_dialog_content = "¡Vaya... Otra batalla?!",
  ui_story_5085_50850302_1_dialog_content = "¡Contempla el poder de la alquimia!",
  ui_story_5085_50850302_2_dialog_content = "Graah...",
  ui_story_5085_50850302_3_dialog_content = "Uf... ¡Eso estuvo cerca! Bueno que tenía suficientes materiales!",
  ui_story_5085_50850302_4_dialog_content = "Hey Ryza, ¿hiciste eso usando alquimia?",
  ui_story_5085_50850302_5_dialog_content = "¡Así es! Bastante impresionante, ¿eh?",
  ui_story_5085_50850302_6_dialog_content = "Eso es un eufemismo, por decir lo menos. Con este tipo de poder, explorar la isla no debería ser un desafío.",
  ui_story_5085_50850302_7_dialog_content = "Sin embargo, eso solo resuelve nuestras preocupaciones de combate. La señorita Vice tenía razón: necesitamos encontrar un lugar adecuado para establecer nuestro campamento base.",
  ui_story_5085_50850302_8_dialog_content = "Sí, tienes razón. Con tantos Eclipsites merodeando, un lugar seguro para elaborar estrategias sería muy útil.",
  ui_story_5085_50850302_9_dialog_content = "Entonces, ¿alguien tiene alguna sugerencia para nuestro campamento?",
  ui_story_5085_50850302_10_dialog_content = "Creo... En algún lugar cerca de la playa sería lo mejor.",
  ui_story_5085_50850302_11_dialog_content = "Por lo que la señorita Barbara y yo vimos antes, gran parte de esta isla parece estar llena de los restos rotos de antiguas ruinas.",
  ui_story_5085_50850302_12_dialog_content = "Lo mismo puede ser cierto para los Eclipsites...",
  ui_story_5085_50850302_13_dialog_content = "Sin embargo, las playas parecen estar mayormente libres de estos restos, lo que puede significar que son nuestra opción más segura. No solo eso, sino que también podemos estar atentos a los barcos que pasan.",
  ui_story_5085_50850302_14_dialog_content = "¡Estaba pensando exactamente lo mismo!",
  ui_story_5085_50850302_15_dialog_content = "Parece que tienes un verdadero ojo para la estrategia.",
  ui_story_5085_50850302_16_dialog_content = "Tú y Ryza son totalmente diferentes... ¡Por eso se complementan tan bien!",
  ui_story_5085_50850302_17_dialog_content = "De hecho, Ryza me ha estado vigilando todo este tiempo.",
  ui_story_5085_50850302_18_dialog_content = "¿De qué estás hablando? Tú eres el que siempre se encarga de cuidarme.",
  ui_story_5085_50850302_19_dialog_content = "¡Sí, sí, entendemos que ustedes dos están muy unidos! ¡Ahora vamos a nuestro próximo objetivo!",
  ui_story_5085_50850302_20_dialog_content = "¡Y eso sería—Construir un hermoso escenario para expresar nuestros sentimientos de amistad!",
  ui_story_5085_50850302_21_dialog_content = "Eh, creo que se refiere a encontrar una playa adecuada para nuestro campamento.",
  ui_story_5085_50850302_22_dialog_content = "¿Qué estás haciendo, Klaudia? ¿Se te cayó algo?",
  ui_story_5085_50850302_23_dialog_content = "Ah, estaba buscando esos restos que mencioné antes. Parece que hay algunos de ellos por ahí...",
  ui_story_5085_50850302_24_dialog_content = "Siempre que Ryza nos lleva a una aventura, tendemos a recoger objetos aparentemente inútiles como este.",
  ui_story_5085_50850302_25_dialog_content = "Nunca se sabe... Algunos de ellos podrían ser materiales de alquimia potentes.",
  ui_story_5085_50850302_26_dialog_content = "Entiendo. ¡Tal vez puedo usar mis poderes para buscar algo útil también!",
  ui_story_5085_50850302_27_dialog_content = "¡Eso suena mucho a la caza del tesoro! Como nativo del desierto de Rediesel, resulta que eso es una de mis fortalezas!",
  ui_story_5085_50850302_28_dialog_content = "Hmm... Esto parece el juguete de un noble antiguo... ¡Aburrido!",
  ui_story_5085_50850302_29_dialog_content = "¡Jajaja! Supongo que debería mencionar que a la gente del Desierto Rediesel no le importa mucho cualquier cosa que no pueda ser adaptada a una máquina enorme.",
  ui_story_5085_50850302_30_dialog_content = "Hablando de máquinas enormes... Alguien estaba buscando información sobre mechas antiguos aquí en la isla.",
  ui_story_5085_50850302_31_dialog_content = "Es extraño... por alguna razón, no puedo recordar quién era.",
  ui_story_5085_50850302_32_dialog_content = "¿De qué tipo de cosas estás hablando? ¿Puedo usar la alquimia en ello?",
  ui_story_5085_50850302_33_dialog_content = "Ryza, cuida tus pasos!",
  ui_story_5085_50850302_34_dialog_content = "... ¡Whoa!",
  ui_story_5085_50850302_35_dialog_content = "Eso estuvo cerca... ¿Cómo es que hay hielo aquí?!",
  ui_story_5085_50850302_36_dialog_content = "Oye... Si lo miras de cerca, el hielo parece extrañamente en forma de flecha...",
  ui_story_5085_50850302_37_dialog_content = "¿Hielo en forma de flecha? Espera... ¿Podría ser?!",
  ui_story_5085_50850302_38_dialog_content = "¡Esto debe ser obra de Zarya!",
  ui_story_5085_50850302_39_dialog_content = "Parece que ella estaba dejando un rastro detrás... Estoy seguro de que la encontraremos si lo seguimos.",
  ui_story_5085_50850302_40_dialog_content = "¡Así que, el amigo del Navegante nos dejó una señal!",
  ui_story_5085_50850302_41_dialog_content = "Me pregunto si Patty hizo lo mismo en otro lugar?",
  ui_story_5085_50850401_1_dialog_content = "Los Eclipsites han sido erradicados. Por favor, deje otra señal aquí, señorita Zarya.",
  ui_story_5085_50850401_2_dialog_content = "Eh... ¡Claro!",
  ui_story_5085_50850401_3_dialog_content = "¿Hay un problema? Pareces preocupado.",
  ui_story_5085_50850401_4_dialog_content = "No, es solo que... Eres mucho más madura de lo que pareces, Lady Patricia.",
  ui_story_5085_50850401_5_dialog_content = "Aunque no apruebas completamente mi plan, has estado ayudándome a eliminar los Eclipsites y dejar señales para los demás...",
  ui_story_5085_50850401_6_dialog_content = "<size=30>Si tan solo pudiera ser un poco más maduro, también...</size>",
  ui_story_5085_50850401_7_dialog_content = "Honestamente, ya te lo dije—",
  ui_story_5085_50850401_8_dialog_content = "Esto no tiene nada que ver con la madurez. Una noble no falta a su palabra fácilmente, especialmente cuando ha acordado hacer algo.",
  ui_story_5085_50850401_9_dialog_content = "Además, no tienes que dirigirte a mí de esa manera. Solo puedes...",
  ui_story_5085_50850401_10_dialog_content = "Hola—",
  ui_story_5085_50850401_11_dialog_content = "Zarya—Por aquí—",
  ui_story_5085_50850401_12_dialog_content = "Es PlayerName!",
  ui_story_5085_50850401_13_dialog_content = "Si alguien nos ha encontrado, entonces eso significa...",
  ui_story_5085_50850401_14_dialog_content = "¡Los marcadores de hielo... Funcionaron!",
  ui_story_5085_50850401_15_dialog_content = "¡Patty! ¡Finalmente te encontramos!",
  ui_story_5085_50850401_16_dialog_content = "¿Ryza?! Oh...",
  ui_story_5085_50850401_17_dialog_content = "¡Tenía la sensación de que tú también estabas en la isla! Esto es bastante la loca reunión, ¿eh?",
  ui_story_5085_50850401_18_dialog_content = "Gracias a Dios que estás a salvo, Patricia.",
  ui_story_5085_50850401_19_dialog_content = "Solo me alegra que todos nos hayamos encontrado... ¿Entonces puedo preguntar quiénes son tus amigos?",
  ui_story_5085_50850401_20_dialog_content = "<color=#e8d9bb>Después de intercambiar breves presentaciones, Patricia explica su situación anterior.</color>",
  ui_story_5085_50850401_21_dialog_content = "Ya veo. Así que has estado trabajando con este Navegante desde que fuimos transportados a este mundo.",
  ui_story_5085_50850401_22_dialog_content = "Siempre pareces atraer a otros buscadores de aventuras donde quiera que vayas, Ryza. Es realmente extraño.",
  ui_story_5085_50850401_23_dialog_content = "No soy solo yo, ya sabes. ¡Nuestros amigos aquí resulta que tienen objetivos similares a nosotros!",
  ui_story_5085_50850401_24_dialog_content = "Ahora entiendo. Por favor permítame presentarme una vez más: Soy Patricia Abelheim, pero puedes llamarme Patty para abreviar. Es un honor conocerlos a todos.",
  ui_story_5085_50850401_25_dialog_content = "¡Vaya, qué introducción...! Suena justo como un caballero!",
  ui_story_5085_50850401_26_dialog_content = "¡Eso es porque Patty es una noble!",
  ui_story_5085_50850401_27_dialog_content = "Ya veo, eso explica por qué me recuerda a un cierto amigo! Ella también es una noble digna, así como una increíble caballera!",
  ui_story_5085_50850401_28_dialog_content = "¡Y con eso, todos mis amigos están contabilizados! ¿Y tú, Navegante?",
  ui_story_5085_50850401_29_dialog_content = "Vamos a ver...",
  ui_story_5085_50850401_30_dialog_content = "Con Zarya encontrado, nuestro grupo también debería estar completo ahora.",
  ui_story_5085_50850401_31_dialog_content = "Hmm... ¿Tal vez deberíamos hacer un último recuento, solo para estar seguros?",
  ui_story_5085_50850401_32_dialog_content = "¡Uno, dos, tres, cuatro! ¡Sí, estamos todos aquí!",
  ui_story_5085_50850401_33_dialog_content = "¿Solo cuatro? Siento que nos falta alguien...",
  ui_story_5085_50850401_34_dialog_content = "¿Quizás solo estás pensando en Corax? Te dijo que también quería venir, ¿recuerdas?",
  ui_story_5085_50850401_35_dialog_content = "Tienes razón... Quizás estoy pensando demasiado en las cosas.",
  ui_story_5085_50850401_36_dialog_content = "Creo que estamos bien ahora, Ryza. ¿Cuál es tu próximo movimiento?",
  ui_story_5085_50850401_37_dialog_content = "Primero, necesito recuperar ese caldero y llevarlo a una playa adecuada. ¡Después de eso, puedo crear un taller para que lo usemos!",
  ui_story_5085_50850401_38_dialog_content = "Una vez que tengamos eso, descansaremos, crearemos montones de objetos útiles y continuaremos con nuestra exploración de las ruinas!",
  ui_story_5085_50850401_39_dialog_content = "¿Qué piensan todos del plan hasta ahora?",
  ui_story_5085_50850401_40_dialog_content = "Aunque estemos en un mundo completamente desconocido... Ryza está tan motivado como siempre.",
  ui_story_5085_50850401_41_dialog_content = "No hay objeciones aquí. Creo que un Atelier será esencial para encontrar nuestro camino a casa.",
  ui_story_5085_50850401_42_dialog_content = "De acuerdo. Las ruinas de la isla relacionadas con la música antigua también son dignas de investigar.",
  ui_story_5085_50850401_43_dialog_content = "Creo que el plan de Ryza es sólido.",
  ui_story_5085_50850401_44_dialog_content = "Como yo lo hice.",
  ui_story_5085_50850401_45_dialog_content = "¡Genial! ¡Me encantaría mantener las llamas de nuestra aventura de verano ardiendo también! ¿Y tú, Navegante?",
  ui_story_5085_50850401_46_dialog_content = "También vinimos a explorar esas ruinas.",
  ui_story_5085_50850401_47_dialog_content = "Pero aún queda la pregunta de cómo vamos a volver al continente...",
  ui_story_5085_50850401_48_dialog_content = "En cualquier caso, ¡no podemos permitirnos volver ahora mismo!",
  ui_story_5085_50850401_49_dialog_content = "Si volvemos a casa con las manos vacías, perderemos nuestro pago Y tendremos que pagar por el barco... Ugh, si hubiera sabido que algo así iba a suceder, habría comprado un seguro contra desastres en Umbraton...",
  ui_story_5085_50850401_50_dialog_content = "Además, ¿quizás encontraremos un barco o algún tipo de dispositivo de comunicación en las ruinas?",
  ui_story_5085_50850401_51_dialog_content = "... Tienes razón. De todos modos, no puedo pensar en una mejor solución ahora mismo...",
  ui_story_5085_50850401_52_dialog_content = "En ese caso, ¡unámonos a la exploración y completemos nuestra misión!",
  ui_story_5085_50850401_53_dialog_content = "¡Guau, parece que todos están muy animados! Ahora bien... Nos vamos a la playa—",
  ui_story_5085_50850401_54_dialog_content = "¡Vamooooos!",
  ui_story_5085_50850501_1_dialog_content = "Ja—Uf—!",
  ui_story_5085_50850501_2_dialog_content = "¡Este lugar debería funcionar muy bien! ¡Gracias de nuevo, a todos!",
  ui_story_5085_50850501_3_dialog_content = "Nunca siquiera consideré usar el hielo de Zarya de esta manera. Realmente transportamos el caldero hasta aquí con la ayuda del hielo...",
  ui_story_5085_50850501_4_dialog_content = "N-No es nada, realmente. Mis poderes no son buenos para mucho más que esto...",
  ui_story_5085_50850501_5_dialog_content = "Se siente como si todo va a funcionar una vez que Ryza pueda realizar su alquimia.",
  ui_story_5085_50850501_6_dialog_content = "Jeje, eso es correcto. La alquimia de Ryza es algo verdaderamente increíble.",
  ui_story_5085_50850501_7_dialog_content = "En cuanto a un lugar adecuado para el taller, echa un vistazo a este lugar, Ryza—",
  ui_story_5085_50850501_8_dialog_content = "Esta parte del bosque proporciona abundante luz solar y agua limpia fácilmente disponible. Es un lugar valioso para establecer un refugio.",
  ui_story_5085_50850501_9_dialog_content = "La playa también está cerca, lo que nos permite ver el océano en cualquier momento.",
  ui_story_5085_50850501_11_dialog_content = "¡No veo por qué no! ¡Estoy seguro de que a todos les gustaría una bonita cabaña junto al mar en el bosque!",
  ui_story_5085_50850501_12_dialog_content = "Estoy listo para comenzar a sintetizar todo lo que necesitamos para construir nuestra cabaña.",
  ui_story_5085_50850501_13_dialog_content = "Entonces iré a buscar a Navegador. Ha estado queriendo ver la alquimia de Ryza durante mucho tiempo.",
  ui_story_5085_50850501_14_dialog_content = "¿Es eso—?",
  ui_story_5085_50850501_15_dialog_content = "¡Guau! ¡Hay tanto!!!",
  ui_story_5085_50850501_16_dialog_content = "Todo tipo de materiales de construcción, cortados y moldeados a especificaciones exactas... ¡Y ella simplemente sigue sacándolos del caldero!",
  ui_story_5085_50850501_17_dialog_content = "Todo lo que hicimos fue echar un montón de cosas ordinarias y aleatorias...",
  ui_story_5085_50850501_18_dialog_content = "¡E-Entonces este es el poder de la alquimia! ¡Es tan útil! Podrías construir una casa entera sin siquiera sudar...",
  ui_story_5085_50850501_19_dialog_content = "¡No se queden ahí parados mientras la señorita Ryza hace todo el trabajo, todos! ¡Empecemos a construir ese taller!",
  ui_story_5085_50850501_20_dialog_content = "¡Aquí vienen!",
  ui_story_5085_50850501_21_dialog_content = "Puedo encargarme de mover toda la madera, ¡así que solo déjamelo a mí!",
  ui_story_5085_50850501_22_dialog_content = "¿Está bien? Son terriblemente pesados...",
  ui_story_5085_50850501_23_dialog_content = "¿Quizás debería hacerlo yo en su lugar? Pedirle a una ídola petite que cargue con vigas de madera parece un poco mal.",
  ui_story_5085_50850501_24_dialog_content = "¿Es eso cierto? ¡Humph! ¡No te atrevas a subestimar al ídolo número uno del Desierto de Rediesel! ¡Arrrrraaaaaagh—",
  ui_story_5085_50850501_25_dialog_content = "<color=#e8d9bb>¡Clang—Snap—Thud—!</color>",
  ui_story_5085_50850501_26_dialog_content = "¡I-Increíble! Ella pudo llevar todos esos materiales de construcción a pesar de su pequeña complexión...",
  ui_story_5085_50850501_27_dialog_content = "¿Qué estás haciendo, Zarya?",
  ui_story_5085_50850501_28_dialog_content = "¿Yo? Eh... Estoy usando mi hielo para crear estructuras de soporte para todos y para enfriar el área.",
  ui_story_5085_50850501_29_dialog_content = "Fue idea de Patty.",
  ui_story_5085_50850501_30_dialog_content = "Es difícil no impresionarse después de ver de lo que eres capaz de hacer, Señorita Zarya.",
  ui_story_5085_50850501_31_dialog_content = "A pesar de tener la <color=#FFB400>misma edad</color> que yo, tus poderes son mucho mayores que los míos... Es algo verdaderamente increíble.",
  ui_story_5085_50850501_32_dialog_content = "...",
  ui_story_5085_50850501_33_dialog_content = "Eh... ¿Dije algo malo?",
  ui_story_5085_50850501_34_dialog_content = "No sé, ¿tú lo hiciste?",
  ui_story_5085_50850501_35_dialog_content = "Uh, podría ser porque mencionaste su edad...",
  ui_story_5085_50850501_36_dialog_content = "¿La edad de la señorita Zarya? ¿Me estás diciendo... Ella y yo en realidad no somos tan cercanos en edad?!",
  ui_story_5085_50850501_37_dialog_content = "Oh chico...",
  ui_story_5085_50850501_39_dialog_content = "...",
  ui_story_5085_50850501_40_dialog_content = "<size=30>Soy <color=#FFB400>117</color>...</size>",
  ui_story_5085_50850501_41_dialog_content = "<size=50>¿¡¿?!?</size>",
  ui_story_5085_50850501_42_dialog_content = "¡Ella realmente encontró el valor para decirlo!",
  ui_story_5085_50850501_X42_dialog_content = "Jeje, espero no estar asustándote.",
  ui_story_5085_50850501_X43_dialog_content = "No voy a mentir, fue un poco sorprendente. Pero cuando lo pienso, también tenemos un amigo que no se parece en nada a su edad real.",
  ui_story_5085_50850501_X44_dialog_content = "Eso es cierto.",
  ui_story_5085_50850501_X45_dialog_content = "Ahora que lo mencionas, tienes razón.",
  ui_story_5085_50850501_43_dialog_content = "¡Ahhhh—Olvídalo y sigamos adelante! ¡Todavía necesitamos construir este taller!!!",
  ui_story_5085_50850501_44_dialog_content = "¡Finalmente hemos terminado, y el caldero está exactamente donde necesita estar!",
  ui_story_5085_50850501_45_dialog_content = "¡Deleita tus ojos con el único Atelier de este mundo, traído a ti por nada más y nada menos que Ryza Stout!",
  ui_story_5085_50850501_46_dialog_content = "Y con nuestro trabajo finalmente completo...",
  ui_story_5085_50850501_47_dialog_content = "¡Es hora de divertirse de verdad en verano! Deja la cocina en mis manos; quiero mostrarle a todos cómo asamos la comida en el Desierto Rediesel!",
  ui_story_5085_50850501_48_dialog_content = "De acuerdo, iré a peinar la playa en busca de cualquier material e ingredientes para la comida.",
  ui_story_5085_50850501_49_dialog_content = "Y yo... haré algunos postres con los ingredientes de todos.",
  ui_story_5085_50850501_50_dialog_content = "No tengo ganas de entrar al agua, así que solo ayudaré a preparar la comida.",
  ui_story_5085_50850501_51_dialog_content = "¡Vamos, Patty! No es divertido a menos que todos vayamos a jugar juntos en la playa...",
  ui_story_5085_50850501_52_dialog_content = "Um... ¿Ryza? Creo que nos estamos olvidando de algo muy importante...",
  ui_story_5085_50850501_53_dialog_content = "Cuando llegamos a este mundo, no trajimos ningún traje de baño.",
  ui_story_5085_50850501_54_dialog_content = "Tienes razón... Siempre podríamos reunir materiales para que yo haga algo... Pero será de noche cuando termine.",
  ui_story_5085_50850501_55_dialog_content = "¡Oh! En realidad... Resulta que tengo un traje de baño extra conmigo.",
  ui_story_5085_50850501_56_dialog_content = "¡¿D-De verdad?!",
  ui_story_5085_50850501_57_dialog_content = "¡Uh-huh! Quería dárselo a Carleen como un regalo... Ella es otra amiga cercana nuestra.",
  ui_story_5085_50850501_58_dialog_content = "Pero siempre está tan ocupada con el trabajo y otros asuntos oficiales. Puede que no tenga la oportunidad de usarlo antes de que termine el verano.",
  ui_story_5085_50850501_59_dialog_content = "Si está bien para ti, eres más que bienvenido a usarlo.",
  ui_story_5085_50850501_60_dialog_content = "<color=#e8d9bb>Un rato después—</color>",
  ui_story_5085_50850501_61_dialog_content = "¡Ah!!",
  ui_story_5085_50850501_62_dialog_content = "¡¿Qué pasa?!",
  ui_story_5085_50850501_63_dialog_content = "¡Este traje de baño se ve increíble! ¡Gracias!",
  ui_story_5085_50850502_1_dialog_content = "¡Hora de jugar en el agua!",
  ui_story_5085_50850502_2_dialog_content = "¡Vaya, qué frío! ¿Estás segura de que no quieres unirte a nosotros, Patty?",
  ui_story_5085_50850502_3_dialog_content = "Positivo. Sin trajes de baño extra... Me niego a avergonzarme delante de todos.",
  ui_story_5085_50850502_4_dialog_content = "¿En serio? ¡Qué lástima, pero bueno! Por aquí, todos; estos son los materiales que vamos a necesitar...",
  ui_story_5085_50850502_5_dialog_content = "<color=#e8d9bb>Chapoteo—</color>",
  ui_story_5085_50850502_6_dialog_content = "¡Guau! ¿S-Señorita Barbara?! ¿Qué estás...",
  ui_story_5085_50850502_7_dialog_content = "Pensé que estábamos jugando, ¿no es así? Será mejor que te muevas, ¡o realmente te lo haré saber! ¡Jajaja!",
  ui_story_5085_50850502_8_dialog_content = "<color=#e8d9bb>¡Chapoteo—!</color>",
  ui_story_5085_50850502_9_dialog_content = "Je... En ese caso, ¡yo tampoco me contendré! ¡Haaa!",
  ui_story_5085_50850502_10_dialog_content = "¡Ah! E-Espera un minuto, todavía no estoy mentalmente preparado para esto...!",
  ui_story_5085_50850502_11_dialog_content = "No es momento para tonterías... ¡Ahora cúbreme, PlayerName!",
  ui_story_5085_50850502_12_dialog_content = "<color=#e8d9bb>¡Chapoteo—!</color>",
  ui_story_5085_50850502_13_dialog_content = "...",
  ui_story_5085_50850502_14_dialog_content = "Así es, ¿eh...",
  ui_story_5085_50850502_15_dialog_content = "¡Espero que todos estén listos para perder!!!",
  ui_story_5085_50850502_16_dialog_content = "<color=#e8d9bb>¡Chapoteo—!</color>",
  ui_story_5085_50850502_17_dialog_content = "<color=#e8d9bb>El sol se pone lentamente mientras juegan y recogen ingredientes para una deliciosa barbacoa. Para cuando sus estómagos están llenos, la noche ya ha caído.</color>",
  ui_story_5085_50850502_18_dialog_content = "Es agradable finalmente relajarse después de un día tan largo y estresante...",
  ui_story_5085_50850502_19_dialog_content = "No me di cuenta de que mis bebidas serían tan populares, ¡o habría hecho más! Afortunadamente, la isla ofrece algunos ingredientes verdaderamente frescos.",
  ui_story_5085_50850502_20_dialog_content = "Naturalmente, tenemos que agradecer a todos los demás por explorar esos materiales, y a la señorita Zarya por proporcionar el hielo!",
  ui_story_5085_50850502_21_dialog_content = "No fue nada... ¡Simplemente eres realmente talentosa cuando se trata de preparar bebidas, señorita Klaudia!",
  ui_story_5085_50850502_22_dialog_content = "Gracias... Aunque nosotros...",
  ui_story_5085_50850502_23_dialog_content = "Aunque pasamos tanto tiempo jugando que olvidamos reunir más materiales...",
  ui_story_5085_50850502_24_dialog_content = "¡Creo que la diversión que tuvimos y los recuerdos que hicimos son aún más importantes!",
  ui_story_5085_50850502_25_dialog_content = "Permítanme agradecer a todos nuevamente por probar mi calamar especial de Rediesel! ¡Hoy puse mi corazón y alma en hacerlo!",
  ui_story_5085_50850502_26_dialog_content = "Aunque realmente no había suficiente para todos, y algunas de las piezas quedaron un poco carbonizadas...",
  ui_story_5085_50850502_27_dialog_content = "¡El sabor todavía era de otro mundo! Si tan solo pudiéramos usar la alquimia para restaurar sus partes exteriores...",
  ui_story_5085_50850502_28_dialog_content = "Hablando de eso... ¿se puede usar la alquimia para restaurar estos fragmentos de reliquias a su forma original?",
  ui_story_5085_50850502_29_dialog_content = "Ah, esas son las piezas que recogimos antes.",
  ui_story_5085_50850502_30_dialog_content = "Recogí algunos yo mismo, pero no estoy seguro si Ryza puede usarlos o no.",
  ui_story_5085_50850502_31_dialog_content = "¡Todos ustedes son ayudantes maravillosos! Gracias por estar atentos a nuevos materiales para mi alquimia!",
  ui_story_5085_50850502_32_dialog_content = "No lo sabremos a menos que lo intentemos, ¿verdad? ¡Veré qué puedo hacer con estas piezas esta noche!",
  ui_story_5085_50850502_33_dialog_content = "Desde que conocí a Ryza, ¡siento como si finalmente tuviera una competencia seria en cuanto a la recolección!",
  ui_story_5085_50850502_34_dialog_content = "Jajaja, esto podría darnos más información sobre las ruinas.",
  ui_story_5085_50850502_35_dialog_content = "No puedo sentir nada de estos fragmentos individuales.",
  ui_story_5085_50850502_36_dialog_content = "Pero una vez que han sido restaurados... ¡Podría ser una historia completamente diferente!",
  ui_story_5085_50850502_37_dialog_content = "Voy a ordenar el taller para que todos puedan descansar bien esta noche.",
  ui_story_5085_50850601_1_dialog_content = "<color=#e8d9bb>Graznido—Graznido—</color>",
  ui_story_5085_50850601_2_dialog_content = "... ¿Eh?! Oh... Supongo que también tienen aves marinas nocturnas en este mundo...",
  ui_story_5085_50850601_3_dialog_content = "Está bien, no deberían despertar a nadie.",
  ui_story_5085_50850601_4_dialog_content = "Todos están agotados después de hoy... Están todos profundamente dormidos.",
  ui_story_5085_50850601_5_dialog_content = "¿Sigues vigilando el caldero, Ryza?",
  ui_story_5085_50850601_6_dialog_content = "¡Así es! Tengo que vigilar de cerca el contenido para asegurarme de que nada salga mal.",
  ui_story_5085_50850601_7_dialog_content = "Mmm, no está mal del todo... Un poco más y los fragmentos deberían volver a su forma original!",
  ui_story_5085_50850601_8_dialog_content = "Parece que no eres ajeno a revolver un caldero toda la noche. Ser un alquimista debe ser realmente duro...",
  ui_story_5085_50850601_9_dialog_content = "La alquimia es el arte de crear algo de la nada. A lo largo de las edades, los alquimistas han experimentado con innumerables ideas y métodos para darnos el conocimiento que tenemos hoy.",
  ui_story_5085_50850601_10_dialog_content = "Ahhh, pero aún no puedo evitar preocuparme. ¿Qué haremos si algo sale mal...?",
  ui_story_5085_50850601_11_dialog_content = "Jaja, entonces me quedaré contigo hasta que esté hecho. ¡Estoy seguro de que todo estará bien!",
  ui_story_5085_50850601_12_dialog_content = "De hecho, cuando usé mis poderes para sentir este caldero... Escuché una voz extraña.",
  ui_story_5085_50850601_13_dialog_content = "Me dijo que regresara.",
  ui_story_5085_50850601_14_dialog_content = "¿Eh?",
  ui_story_5085_50850601_15_dialog_content = "¿Es así? ¿Crees que era el caldero el que te hablaba?",
  ui_story_5085_50850601_16_dialog_content = "Quizás. Mis poderes psíquicos me dicen que esta voz está de alguna manera conectada con las ruinas.",
  ui_story_5085_50850601_17_dialog_content = "Sonaba como un espíritu antiguo... Y trató de comunicarse conmigo hablando como si me conociera.",
  ui_story_5085_50850601_18_dialog_content = "No estoy seguro de si seguir o no esta pista. Ni siquiera sé por dónde podría empezar...",
  ui_story_5085_50850601_19_dialog_content = "¡Tengo una pregunta!",
  ui_story_5085_50850601_20_dialog_content = "Se trata de tus poderes. Si no puedes sentir a ningún Eclipsite alrededor, eso significa que no nos encontraremos con ninguno, ¿verdad?",
  ui_story_5085_50850601_21_dialog_content = "Sí, eso suele ser el caso...",
  ui_story_5085_50850601_22_dialog_content = "Ya veo. Qué poder tan interesante... ¡Jah!",
  ui_story_5085_50850601_23_dialog_content = "<color=#e8d9bb>¡Wham!</color>",
  ui_story_5085_50850601_24_dialog_content = "¡¿Q-Qué fue eso...?!",
  ui_story_5085_50850601_25_dialog_content = "No te preocupes, solo fue un error. Parece que hay algunas cosas que incluso tus poderos no pueden detectar, ¿eh?",
  ui_story_5085_50850601_26_dialog_content = "Parece un mosquito, ¡pero míralo más de cerca! Sus ojos son completamente rojos, y desaparece poco después de que lo maté... Hay una buena posibilidad de que sea algún tipo de mosquito Eclipsite.",
  ui_story_5085_50850601_27_dialog_content = "¡Y aún así no lo notaste! ¿Podría esto significar que la isla posee otras propiedades únicas?",
  ui_story_5085_50850601_28_dialog_content = "Seguro que se ve así...",
  ui_story_5085_50850601_29_dialog_content = "Esta isla realmente está llena de misterios.",
  ui_story_5085_50850601_30_dialog_content = "Estoy de acuerdo, y algo me dice que la isla y sus ruinas también quieren que descubramos sus secretos.",
  ui_story_5085_50850601_32_dialog_content = "Es gracioso, me estabas contando tu historia antes de que ese pájaro interrumpiera...",
  ui_story_5085_50850601_33_dialog_content = "Pero ahora, estás escuchándome hablar sobre mis preocupaciones...",
  ui_story_5085_50850601_35_dialog_content = "Si alguna vez encontramos el tiempo, ¡todavía quiero escuchar más sobre tus aventuras!",
  ui_story_5085_50850601_37_dialog_content = "Parece que realmente amas las aventuras, Ryza.",
  ui_story_5085_50850601_38_dialog_content = "¡Pero puedo relacionar totalmente, porque yo también lo hago!",
  ui_story_5085_50850601_39_dialog_content = "Ya sea viendo cosas nuevas y extrañas o viajando con mis amigos... ¡Siempre aprecio cada momento de cada aventura!",
  ui_story_5085_50850601_40_dialog_content = "<color=#e8d9bb>Entre los dos espíritus afines, el caldero de alquimia parece resonar con su pasión por la aventura y emite un sonido prometedor.</color>",
  ui_story_5085_50850601_41_dialog_content = "¡Lo hicimos!",
  ui_story_5085_50850601_42_dialog_content = "Los fragmentos han sido restaurados a su forma original... Espera, ¡ahora hay tres de ellos! ¿Alguna idea de qué es esto?",
  ui_story_5085_50850601_43_dialog_content = "Es...",
  ui_story_5085_50850601_44_dialog_content = "... ¿Algún tipo de <color=#FFB400>emblema</color>?",
  ui_story_5085_50850601_45_dialog_content = "Lo es, ¡y hay tres tipos diferentes de ellos! ¡Todos son tan bonitos!",
  ui_story_5085_50850601_46_dialog_content = "¡Mira este! Parece que algo está grabado en él... ¿Un escudo, tal vez? Me pregunto qué podría significar?",
  ui_story_5085_50850601_47_dialog_content = "Déjame intentar sentirlo.",
  ui_story_5085_50850601_48_option_content = "¡Potencia de fuerza!",
  ui_story_5085_50850601_49_dialog_content = "Mi príncipe, no queda mucho tiempo. Debemos tomar una decisión antes de que sea demasiado tarde.",
  ui_story_5085_50850601_50_dialog_content = "La antigua reliquia que nos has presentado funciona bastante bien, pero aún no hemos dominado sus controles.",
  ui_story_5085_50850601_51_dialog_content = "Las filas de los Eclipsites aumentan con cada día que pasa, y nos duele verte en un estado tan desaliñado y ansioso...",
  ui_story_5085_50850601_52_dialog_content = "El Músico nos dice que planeas dejar el reino y viajar a una tierra lejana.",
  ui_story_5085_50850601_53_dialog_content = "Pero no importa lo que suceda, su Alteza... Siempre honraremos su decisión...",
  ui_story_5085_50850601_54_dialog_content = "¿Son estos los recuerdos del caballero en ese emblema? Parece que está hablando de las ruinas de la isla... ¡Esto incluso podría contarnos más sobre la teleportación!",
  ui_story_5085_50850601_55_dialog_content = "Por favor, ¿puedes mostrarme cómo usar el poder de las ruinas?",
  ui_story_5085_50850601_56_dialog_content = "Regresar.",
  ui_story_5085_50850601_57_dialog_content = "... ¡Esa voz otra vez! ¿Quién eres tú?! ¿Podría ser que tú eres...",
  ui_story_5085_50850601_58_dialog_content = "¡Regresa! Tu gloria te espera...!",
  ui_story_5085_50850601_59_dialog_content = "<size=50>\"¡Porque cuando el príncipe errante regrese, también lo hará la gloria de nuestro reino!\"</size>",
  ui_story_5085_50850601_60_dialog_content = "... ¿¡¿Eh?!?",
  ui_story_5085_50850601_61_option_content = "Mente... ¡Enlace mental!",
  ui_story_5085_50850601_62_dialog_content = "Urgh...",
  ui_story_5085_50850601_63_dialog_content = ".. ¡PlayerName! ¿Qué te pasa?!",
  ui_story_5085_50850601_64_dialog_content = "¡No intentes hacerlo todo tú solo! Todavía me tienes a mí, así como al resto de nuestros amigos!",
  ui_story_5085_50850601_65_dialog_content = "... Amigos...",
  ui_story_5085_50850601_66_dialog_content = "Hay rumores de antiguos mechs en las ruinas. Mi curiosidad estaba superándome. Tenía que verlo por mí mismo.",
  ui_story_5085_50850601_67_dialog_content = "¡O algunos mechas antiguos legendarios!",
  ui_story_5085_50850601_68_dialog_content = "... ¡Es Fleur! ¡Esta es la voz de Fleur! ¿Qué le has hecho?!",
  ui_story_5085_50850601_69_dialog_content = "Regresa... Vuelve... a las ruinas...",
  ui_story_5085_50850601_70_dialog_content = "¡No, aléjate! ¡Las ruinas son peligrosas! La conciencia alojada dentro de ellas ha alterado mis recuerdos y se ha apoderado de mi cuerpo!",
  ui_story_5085_50850601_71_dialog_content = "¡Hagas lo que hagas... No te acerques a las ruinas!!!",
  ui_story_5085_50850601_72_dialog_content = "!!!",
  ui_story_5085_50850601_73_dialog_content = "¡PlayerName! ¡Despierta!",
  ui_story_5085_50850601_74_dialog_content = "¡Los Eclipsites aparecieron mientras estabas usando tus poderes! ¡Tenemos que luchar!",
  ui_story_5085_50850602_1_dialog_content = "¡Ja! ¡No hay escapatoria!",
  ui_story_5085_50850602_2_dialog_content = "Ryza! ¡Navegador!",
  ui_story_5085_50850602_3_dialog_content = "¡Escuchamos una perturbación por aquí! ¿Alguno de ustedes está herido?",
  ui_story_5085_50850602_4_dialog_content = "No, estamos bien...",
  ui_story_5085_50850602_5_dialog_content = "Un enorme ruido acaba de rugir por toda la isla, como si todo comenzara a moverse o algo así.",
  ui_story_5085_50850602_6_dialog_content = "Los Eclipsites parecen mucho más agitados también.",
  ui_story_5085_50850602_7_dialog_content = "Vaya, me pregunto si nos hemos topado con otro secreto.",
  ui_story_5085_50850602_8_dialog_content = "¿¡Q-Qué tipo de secreto estás hablando?!",
  ui_story_5085_50850602_9_dialog_content = "Tiene que ver con los emblemas que restauramos y el reino que solía existir aquí... ¡Y también con lo que esta isla nos ha hecho!",
  ui_story_5085_50850602_10_dialog_content = "<color=#e8d9bb>Bajo la lúgubre luz de la luna, la historia del antiguo reino se revela lentamente a todos...</color>",
  ui_story_5085_50850602_11_dialog_content = "... Y eso es más o menos lo que pasó. ¡Tenemos que rescatar a Fleur y deshacernos de la presencia malévola que controla su cuerpo!",
  ui_story_5085_50850602_12_dialog_content = "Una magia que puede borrar los recuerdos de los amigos... Qué despreciable.",
  ui_story_5085_50850602_13_dialog_content = "Aunque ahora lo recuerdo, todavía me siento terrible por olvidarlo...",
  ui_story_5085_50850602_14_dialog_content = "¡Cómo se atreven esas ruinas apestosas a lanzarme un hechizo! Marca mis palabras, las convertiré en un montón de escombros aún más grande antes de que terminemos aquí!",
  ui_story_5085_50850602_15_dialog_content = "Así parece... El poder de estas ruinas es lo que nos trajo aquí desde nuestro propio mundo...",
  ui_story_5085_50850602_17_dialog_content = "Basado en lo que Ryza y el Navegante, estos tres emblemas podrían ser la clave para derrotar las ruinas.",
  ui_story_5085_50850602_18_dialog_content = "¡No importa lo que pueda ser esto, no llegaremos a ninguna parte a menos que lo investiguemos nosotros mismos!",
  ui_story_5085_50850602_20_dialog_content = "Estoy de acuerdo. Ya sea el resentimiento persistente de alguien o la tecnología del pasado, siempre hay una solución. ¡Ahora preparémonos para irnos!",
  ui_story_5085_50850602_21_dialog_content = "Mientras todos están haciendo sus preparativos, sentiré los otros dos emblemas y veré qué más puedo encontrar.",
  ui_story_5085_50850701_1_dialog_content = "¡Potencia de fuerza!",
  ui_story_5085_50850701_2_dialog_content = "Tres emblemas... corresponden a los tres compañeros más cercanos del príncipe.",
  ui_story_5085_50850701_3_dialog_content = "Un valiente caballero que combate a los enemigos con su espada...",
  ui_story_5085_50850701_4_dialog_content = "Un mago que estudia la historia antigua en busca de sabiduría arcana...",
  ui_story_5085_50850701_5_dialog_content = "Y un músico de corte, cuyas melodías pueden fortalecer incluso los corazones más vacilantes...",
  ui_story_5085_50850701_6_dialog_content = "Eran los súbditos más leales del príncipe, y lucharon a su lado en las buenas y en las malas.",
  ui_story_5085_50850701_7_dialog_content = "Pero cuando se fue, los tres se quedaron atrás para anunciar su regreso...",
  ui_story_5085_50850701_8_dialog_content = "\"¡Porque cuando el príncipe errante regrese, también lo hará la gloria de nuestro reino!\"",
  ui_story_5085_50850701_9_dialog_content = "Veo. Entonces eso es lo que significa.",
  ui_story_5085_50850701_10_dialog_content = "Pero el reino no es más que ruinas ahora... Y encima de eso, las ruinas han perdido completamente el control.",
  ui_story_5085_50850701_11_dialog_content = "¿Significa esto que el príncipe nunca regresó, a pesar de que su reino estaba siendo atacado por los Eclipsites?",
  ui_story_5085_50850701_12_dialog_content = "Mientras tanto, sus tres amigos más cercanos se quedaron en la isla para esperarlo...",
  ui_story_5085_50850701_13_dialog_content = "Pero ahora que ninguno de ellos está aquí, la conciencia dentro de las ruinas ha comenzado a perder el control lentamente...",
  ui_story_5085_50850701_14_dialog_content = "¿Eligiendo al azar a las personas para apresarlas en nombre del príncipe?",
  ui_story_5085_50850701_16_dialog_content = "¿Por qué abandonaría la isla cuando tenía la protección tanto de las antiguas ruinas como de sus amigos más cercanos?",
  ui_story_5085_50850701_18_dialog_content = "Puede que suene como un cobarde... ¿Pero tal vez tenía una razón para no regresar?",
  ui_story_5085_50850701_19_dialog_content = "Bueno, no nos acercaremos más a la verdad si seguimos sentados y adivinando así.",
  ui_story_5085_50850701_20_dialog_content = "Las respuestas probablemente nos estén esperando al final de nuestra aventura.",
  ui_story_5085_50850701_21_dialog_content = "¡Así es! Nuestra misión es descubrir los secretos de esas ruinas y rescatar al amigo del Navegante!",
  ui_story_5085_50850701_22_dialog_content = "De acuerdo. El camino por delante no será fácil, pero no podemos permitirnos retroceder.",
  ui_story_5085_50850702_1_dialog_content = "<color=#e8d9bb>Mientras avanzábamos por el bosque, mantuve mi mente alerta para cualquier señal de nuestro objetivo.</color>",
  ui_story_5085_50850702_2_dialog_content = "<color=#e8d9bb>Pero cuando alcanzamos la cima de una montaña, las ruinas finalmente aparecieron a la vista.</color>",
  ui_story_5085_50850702_3_dialog_content = "¡Nosotros... finalmente... llegamos a este punto!",
  ui_story_5085_50850702_4_dialog_content = "¿Es esta antigua puerta de piedra la entrada a las ruinas? Si es así... ¿Cómo se supone que entremos...?",
  ui_story_5085_50850702_5_dialog_content = "¡Oigan! Miren estas ranuras en la puerta, ¡todos!",
  ui_story_5085_50850702_6_dialog_content = "¡Parecen coincidir perfectamente con la forma de esos tres emblemas! ¡Quizás realmente sean las llaves!",
  ui_story_5085_50850702_7_dialog_content = "PlayerName, ¿puedes sentir si hay algún Eclipsites cerca?",
  ui_story_5085_50850702_8_option_content = "Enlace mental!",
  ui_story_5085_50850702_9_dialog_content = "No hay Eclipsites en el otro lado de la puerta, pero...",
  ui_story_5085_50850702_10_dialog_content = "Definitivamente hay algo allí...",
  ui_story_5085_50850702_11_dialog_content = "¿Tú también puedes sentirlo, Ryza?",
  ui_story_5085_50850702_12_dialog_content = "Quizás sea porque estoy sosteniendo este emblema, pero siento un poderoso anhelo que viene del otro lado. Es tan triste... Y sin embargo, extrañamente reconfortante.",
  ui_story_5085_50850702_13_dialog_content = "Simplemente coloquemos los emblemas en su lugar primero.",
  ui_story_5085_50850702_14_dialog_content = "<color=#e8d9bb>Haz clic, haz clic, haz clic-</color>",
  ui_story_5085_50850702_15_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_5085_50850702_16_dialog_content = "¡¿Q-Qué está pasando?!",
  ui_story_5085_50850702_17_dialog_content = "Espera... ¡Alguien viene!",
  ui_story_5085_50850702_18_dialog_content = "¡Allí arriba!!",
  ui_story_5085_50850702_19_dialog_content = "Tienes razón... ¡¿Pero cuándo aparecieron?!",
  ui_story_5085_50850702_20_dialog_content = "Bienvenido a mi reino—",
  ui_story_5085_50850702_21_dialog_content = "¿F-Fleur?!",
  ui_story_5085_50850702_22_dialog_content = "No, ¡es la conciencia dentro de las ruinas! Está controlando el cuerpo de Fleur...",
  ui_story_5085_50850702_23_dialog_content = "¡Y obligándolo a actuar como el \"príncipe errante\"!",
  ui_story_5085_50850702_24_dialog_content = "Te deseo buenos días, mi errante amigo Caelestite.",
  ui_story_5085_50850702_25_dialog_content = "Los actores en esta obra importan poco. En su búsqueda de ti, se topó con este lugar...",
  ui_story_5085_50850702_26_dialog_content = "Y así las ruinas lo convirtieron en el príncipe.",
  ui_story_5085_50850702_27_dialog_content = "Ah, ¡cómo he lamentado la pérdida de mi reino, y cómo ni una sola alma vino en su defensa! Pero ahora, ha llegado el momento de convocar a mis súbditos más leales.",
  ui_story_5085_50850702_28_option_content = "¡Potencia de fuerza!",
  ui_story_5085_50850702_29_dialog_content = "¡Fleur! ¡Animarse!",
  ui_story_5085_50850702_30_dialog_content = "¡Guau—",
  ui_story_5085_50850702_31_dialog_content = "Mi cabeza... Está latiendo de repente...",
  ui_story_5085_50850702_32_dialog_content = "T-Tu poder no está funcionando, ! Usarlos solo hará que el \"príncipe\" ejerza presión psíquica sobre todos nosotros...",
  ui_story_5085_50850702_33_dialog_content = "Tus desesperados gritos son música para mis oídos. A través de tus propias acciones imprudentes, has traído dolor y sufrimiento a tus súbditos—",
  ui_story_5085_50850702_34_dialog_content = "¡No son mis súbditos! ¡Son mis amigos! Y—",
  ui_story_5085_50850702_35_dialog_content = "¡¡¡Tú también eres uno de nosotros!!!",
  ui_story_5085_50850702_36_dialog_content = "...",
  ui_story_5085_50850702_37_dialog_content = "Yo... soy un actor... Bendecido con los recuerdos del príncipe...",
  ui_story_5085_50850702_38_dialog_content = "Ejem... Ahora, continuemos con nuestra gloriosa actuación...",
  ui_story_5085_50850702_39_dialog_content = "¡Viajeros de lejos! ¿Qué prueba tienen de identificarse como mis sujetos más leales?",
  ui_story_5085_50850702_40_dialog_content = "Solo hay un camino a seguir: ¡completa mis misiones y despierta los recuerdos dentro de estos emblemas!",
  ui_story_5085_50850702_41_dialog_content = "Solo entonces te concederé el paso.",
  ui_story_5085_50850702_42_dialog_content = "¿Ah?? ¿Eso significa que nos dejarás entrar en las ruinas?",
  ui_story_5085_50850702_43_dialog_content = "Solo necesitamos completar estas \"misiones\", ¿verdad?",
  ui_story_5085_50850702_44_dialog_content = "¡Entonces todavía hay esperanza! Mientras logremos entrar en las ruinas, tenemos la oportunidad de salvar a Fleur!",
  ui_story_5085_50850702_45_dialog_content = "¡Escuchen mis palabras, viajeros! Las misiones de los Emblemas del Caballero—",
  ui_story_5085_50850702_46_dialog_content = "\"Mata a cien monstruos chupasangres, para que nuestro reino finalmente pueda dormir en paz y comodidad.\"",
  ui_story_5085_50850702_47_dialog_content = "\"Monstruos chupasangre\"...? ¿D-De verdad hay criaturas tan aterradoras en esta isla?",
  ui_story_5085_50850702_48_dialog_content = "Un monstruo chupasangre... ¿Podría ser esa cosa que vi con PlayerName antes?",
  ui_story_5085_50850702_49_dialog_content = "Lo siguiente es la misión del Emblema del Músico—",
  ui_story_5085_50850702_50_dialog_content = "\"Ofrece a los soldados de nuestro reino una noche de sueño reparador con la canción de cuna más relajante del mundo.\"",
  ui_story_5085_50850702_51_dialog_content = "... ¿Una canción de cuna?!",
  ui_story_5085_50850702_52_dialog_content = "¡Ese es el peor escenario posible para un ídolo de rock duro como yo!",
  ui_story_5085_50850702_53_dialog_content = "Y finalmente, la búsqueda del Emblema del Mago—",
  ui_story_5085_50850702_54_dialog_content = "\"Invoque un viento milagroso para acunar el palacio en una suave y agradable brisa para siempre.\"",
  ui_story_5085_50850702_55_dialog_content = "...",
  ui_story_5085_50850702_56_dialog_content = "...",
  ui_story_5085_50850702_57_dialog_content = "¿Por qué todas estas misiones tienen algo que ver con dormir?!?",
  ui_story_5085_50850702_58_dialog_content = "Jejeje... Parece que el príncipe tiene un serio insomnio...",
  ui_story_5085_50850702_59_dialog_content = "¿Es por esto que el príncipe dejó su reino en primer lugar? Ridículo—",
  ui_story_5085_50850702_60_dialog_content = "Me pregunto... ¿Cómo se supone que debemos crear una brisa perpetua para \"acunar el palacio\"?",
  ui_story_5085_50850702_62_dialog_content = "Cuando los tres emblemas despierten, nuestro reino nacerá de nuevo.",
  ui_story_5085_50850702_63_dialog_content = "Estoy seguro de que... Tú encontrarás las respuestas.",
  ui_story_5085_50850702_64_dialog_content = "Qué conjunto de misiones tan problemático.",
  ui_story_5085_50850702_65_dialog_content = "Solo estoy agradecido de que nos hayan dado un camino a seguir. Al menos sabemos lo que tenemos que hacer ahora.",
  ui_story_5085_50850702_66_dialog_content = "¿Qué piensas, Ryza?",
  ui_story_5085_50850702_67_dialog_content = "Sigamos avanzando. Estoy seguro de que la respuesta se revelará pronto.",
  ui_story_5085_50850702_68_dialog_content = "De hecho... ¡Ya tengo algunas ideas para completar estas misiones!",
  ui_story_5085_50850800_1_dialog_content = "¡Uh-oh, tenemos más Eclipsites!",
  ui_story_5085_50850800_2_dialog_content = "¿Dónde se supone que debemos encontrar estos \"monstruos chupasangre\" para la búsqueda del Caballero?",
  ui_story_5085_50850800_3_dialog_content = "¡De hecho, el Navegante y yo ya tenemos un plan para eso!",
  ui_story_5085_50850800_4_dialog_content = "¡Por eso creo que la misión del Emblema del Caballero no debería ser un problema para nosotros!",
  ui_story_5085_50850800_5_dialog_content = "La búsqueda del Mago probablemente será la más problemática... ¿Cómo se supone que debemos crear algo que pueda invocar una brisa perpetua?",
  ui_story_5085_50850800_6_dialog_content = "De hecho, tengo algunas ideas que podrían serte útiles, Ryza!",
  ui_story_5085_50850900_1_dialog_content = "Excelente... Gracias a la ayuda de la Srta. Vice, parece que Ryza ha descubierto una nueva dirección para explorar con su alquimia.",
  ui_story_5085_50850900_2_dialog_content = "¿En serio? ¡Eso es genial! También he estado progresando de mi lado.",
  ui_story_5085_50850900_3_dialog_content = "¡Pronto, tendremos dos emblemas despertados en nuestra posesión!",
  ui_story_5085_50850900_4_dialog_content = "¿Y tú, Klaudia? Parece que tú y Barbara están trabajando bastante bien juntos.",
  ui_story_5085_50850900_5_dialog_content = "Hemos hecho mucho progreso también, pero todavía estoy un poco nervioso...",
  ui_story_5085_50850902_1_dialog_content = "Perdón por la espera—",
  ui_story_5085_50850902_2_dialog_content = "Creo... creo que lo hemos hecho!",
  ui_story_5085_50850902_3_dialog_content = "¡Apuesto a que el príncipe no esperaba que completáramos sus misiones tan rápido!",
  ui_story_5085_50850902_4_dialog_content = "Oye—conciencia de las ruinas, o quienquiera que seas—",
  ui_story_5085_50850902_5_dialog_content = "¡Hemos terminado con tus tres misiones!",
  ui_story_5085_50850902_6_dialog_content = "... Debes decirme primero cómo lograste tus objetivos.",
  ui_story_5085_50850902_7_dialog_content = "Empecemos.",
  ui_story_5085_50850902_8_dialog_content = "¡Correcto!",
  ui_story_5085_50850902_9_dialog_content = "¡Primero, el Emblema del Caballero!",
  ui_story_5085_50850902_10_dialog_content = "... Zarya y yo completamos eso juntos!",
  ui_story_5085_50850902_11_dialog_content = "C-Como guardián real de Queen Bethlehem... ¡Estoy más que dispuesto a emprender una búsqueda de caballero!",
  ui_story_5085_50850902_12_dialog_content = "¡Con nuestra fuerza combinada, eliminamos cien mosquitos Eclipsite de la isla!",
  ui_story_5085_50850902_13_dialog_content = "Eso debería satisfacer el requisito de la misión de matar a \"cien monstruos chupasangre\", ¿verdad?",
  ui_story_5085_50850902_14_dialog_content = "Solo desearía que pudiéramos haber incluido al que Ryza y yo golpeamos la noche anterior...",
  ui_story_5085_50850902_15_dialog_content = "¡A continuación, el Emblema del Músico!",
  ui_story_5085_50850902_16_dialog_content = "¡Sí, sí, sí! Cuando se trata de música, ningún desafío es demasiado grande para la ídolo número uno, Barbara!",
  ui_story_5085_50850902_17_dialog_content = "Y con el increíble apoyo de la señorita Klaudia...",
  ui_story_5085_50850902_18_dialog_content = "¡Nuestra ya maravillosa música se convirtió en una fuerza imparable de superioridad sónica!",
  ui_story_5085_50850902_19_dialog_content = "Jeje, simplemente proporcioné acompañamiento instrumental para la hermosa voz de la señorita Barbara.",
  ui_story_5085_50850902_20_dialog_content = "¡Su canto es verdaderamente espectacular!",
  ui_story_5085_50850902_21_dialog_content = "Todo lo que hicimos fue cambiar el modo de expresión; ¡el amor en mi corazón aún arde tan caliente como siempre!",
  ui_story_5085_50850902_22_dialog_content = "¡Y con eso, les dimos a los soldados del reino la canción de cuna más dulce que jamás hayan escuchado!",
  ui_story_5085_50850902_23_dialog_content = "¡Y finalmente, el Emblema del Mago!",
  ui_story_5085_50850902_24_dialog_content = "¡Mira! Este es el poder—",
  ui_story_5085_50850902_25_dialog_content = "¡De mi alquimia! Con la ayuda de todos, ¡creamos el generador de viento definitivo!",
  ui_story_5085_50850902_26_dialog_content = "Proporcioné el diseño, Zarya proporcionó los cubitos de hielo y Ryza proporcionó las partes. Después de eso, todos trabajamos juntos para ensamblarlo.",
  ui_story_5085_50850902_27_dialog_content = "Aunque en Illumina, nos referiríamos a ello como un \"aire acondicionado\" o algo por el estilo...",
  ui_story_5085_50850902_28_dialog_content = "¡Pero el nombre no es importante!",
  ui_story_5085_50850902_29_dialog_content = "¡Con esta máquina, pudimos invocar un viento milagroso para \"acunar el palacio en una suave y agradable brisa\"!",
  ui_story_5085_50850902_30_dialog_content = "Para los antiguos aurorianos que alguna vez vivieron aquí, ¡un dispositivo tan avanzado y conveniente habría sido incluso más impresionante que la magia!",
  ui_story_5085_50850902_31_dialog_content = "Ya veo... Así que estas son las respuestas que me has traído.",
  ui_story_5085_50850902_32_dialog_content = "Aún así...",
  ui_story_5085_50850902_33_dialog_content = "Antes de permitirte la entrada, debo estar seguro de tu lealtad.",
  ui_story_5085_50850902_34_dialog_content = "¡Ahora debes demostrarme que la amistad vale más que el oro!",
  ui_story_5085_50850902_35_dialog_content = "¡Después de todo ese correteo, ahora quieres que demostremos nuestra amistad?!",
  ui_story_5085_50850902_36_dialog_content = "¿Tal vez solo quiere que demostremos la amistad entre el príncipe y los dueños de estos emblemas?",
  ui_story_5085_50850902_37_dialog_content = "¡Pero eso es completamente redundante!",
  ui_story_5085_50850902_38_dialog_content = "Está bien, ¡estaré encantado de demostrártelo!",
  ui_story_5085_50850902_39_dialog_content = "¿Ah?",
  ui_story_5085_50850902_40_dialog_content = "¡Y eso es porque—Somos los amigos más cercanos del príncipe!",
  ui_story_5085_50850902_41_dialog_content = "Todo lo que hemos hecho hasta ahora es en servicio del príncipe \"actual\". Eso es completamente cierto.",
  ui_story_5085_50850902_42_dialog_content = "¡Y si no me crees, usaré el calor de mis manos para demostrártelo!",
  ui_story_5085_50850902_43_dialog_content = "...",
  ui_story_5085_50850902_44_dialog_content = "¡Vamos, todos! ¡Ayuden al Navegante a abrir la puerta!",
  ui_story_5085_50850902_45_dialog_content = "Ryza... PlayerName...",
  ui_story_5085_50850902_46_dialog_content = "¡No podemos permitirnos ser detenidos en un lugar como este! ¡Vamos!",
  ui_story_5085_50850902_47_dialog_content = "¡También ayudaré a PlayerName!",
  ui_story_5085_50850902_48_dialog_content = "¡Uno de los nuestros de Rediesel Wrench está allí! ¡Tengo el deber de traerlo a casa!",
  ui_story_5085_50850902_49_dialog_content = "¡Me juré a mí mismo... Que nunca volvería a perder contra nadie nunca más!",
  ui_story_5085_50850902_50_dialog_content = "\"Pon tus manos en la puerta y ábrela con tu corazón.\"",
  ui_story_5085_50850902_51_dialog_content = "Esta calidez... Esta pasión...",
  ui_story_5085_50850902_52_dialog_content = "La gloria de nuestro pasado finalmente ha resurgido.",
  ui_story_5085_50850902_53_dialog_content = "¡Las puertas de mi reino están abiertas para ti!",
  ui_story_5085_50850902_54_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5085_50850902_55_dialog_content = "¡Lo hicimos!",
  ui_story_5085_50851001_1_dialog_content = "¡Finalmente llegamos a las ruinas!",
  ui_story_5085_50851001_2_dialog_content = "¡Vaya, es igual de increíble por dentro! ¡Apuesto a que este lugar se veía realmente impresionante en su día!",
  ui_story_5085_50851001_3_dialog_content = "Aún deberíamos ser cautelosos. El tiempo ha desgastado gran parte del interior...",
  ui_story_5085_50851001_4_dialog_content = "No podemos olvidarnos de la conciencia tampoco. No hay forma de saber qué está tramando ahora mismo.",
  ui_story_5085_50851001_5_dialog_content = "¡Ugh! Finalmente conseguimos abrir la puerta, pero Fleur no se encuentra por ninguna parte de nuevo!",
  ui_story_5085_50851001_6_dialog_content = "Mira allá—¿Es ese el trono?",
  ui_story_5085_50851001_7_dialog_content = "¡Hay alguien sentado en él! Tal vez sea Fleur...",
  ui_story_5085_50851001_8_dialog_content = "¡Oye, realmente es él!",
  ui_story_5085_50851001_9_dialog_content = "¡Fleur—!",
  ui_story_5085_50851001_10_dialog_content = "...",
  ui_story_5085_50851001_11_option_content = "Enlace mental—",
  ui_story_5085_50851001_12_dialog_content = "<color=#e8d9bb>Crepitar-</color>",
  ui_story_5085_50851001_13_dialog_content = "No recuerdo cuándo comenzó, pero los Eclipsites comenzaron a atacarnos todas las noches.",
  ui_story_5085_50851001_14_dialog_content = "Hasta el día de hoy, todavía no sé cuándo o por qué aparecieron, pero han traído a mi gente un dolor y sufrimiento incontables.",
  ui_story_5085_50851001_15_dialog_content = "Noche tras noche insomne, observé cómo mis amigos y seres queridos eran arrebatados de mí uno a uno.",
  ui_story_5085_50851001_16_dialog_content = "Y así he decidido dejar el reino y buscar ayuda en el continente. El rey no debería ser forzado a enfrentar esta crisis solo.",
  ui_story_5085_50851001_17_dialog_content = "Oh sabio y antiguo espíritu de las ruinas... Por favor, recuerda mis intenciones.",
  ui_story_5085_50851001_18_dialog_content = "Si debo regresar victorioso, prométeme que cantarás mis alabanzas. Pero si nunca regreso, por favor no me llores...",
  ui_story_5085_50851001_19_dialog_content = "Estos <color=#FFB400>tres emblemas</color> simbolizan a tres personas de la más alta moral.",
  ui_story_5085_50851001_20_dialog_content = "En las manos de los dignos, estos emblemas traerán nueva vida a nuestro reino algún día...",
  ui_story_5085_50851001_21_dialog_content = "Príncipe...",
  ui_story_5085_50851001_22_dialog_content = "¿Bien?",
  ui_story_5085_50851001_23_dialog_content = "... Fleur aún no ha recuperado la conciencia, pero creo que sé por qué tú y tus amigos fueron convocados a este mundo, Ryza...",
  ui_story_5085_50851001_24_dialog_content = "¡¿Eh?!",
  ui_story_5085_50851001_25_dialog_content = "El príncipe dejó la isla para pedir ayuda al continente, y confió las ruinas con su último mensaje.",
  ui_story_5085_50851001_26_dialog_content = "Si él no lograba regresar, el reino debía ser dejado en manos de las tres personas que portaban estos emblemas...",
  ui_story_5085_50851001_27_dialog_content = "El Caballero, el Mago y el Músico...?",
  ui_story_5085_50851001_28_dialog_content = "Entonces eso debe significar... El príncipe nunca volvió...",
  ui_story_5085_50851001_29_dialog_content = "Así es, y en los innumerables años siguientes a la caída de su reino...",
  ui_story_5085_50851001_30_dialog_content = "Las ruinas han estado esperando el regreso del príncipe, y buscando sin cesar a tres personas dignas para tomar estos emblemas y restaurar el reino.",
  ui_story_5085_50851001_31_dialog_content = "Y dado que todos eran dignos de los emblemas, las ruinas los convocaron aquí desde otro mundo por error. Si tuviera que adivinar, probablemente eso fue alrededor del momento en que Fleur fue confundido con el príncipe y quedó atrapado aquí.",
  ui_story_5085_50851001_32_dialog_content = "¡Así es como sucedió! Entonces el verdadero príncipe...",
  ui_story_5085_50851001_33_dialog_content = "Ya sea que haya regresado a salvo o no, ahora no es más que un sueño inalcanzable.",
  ui_story_5085_50851001_34_dialog_content = "¡Qué terrible manera de terminar las cosas...",
  ui_story_5085_50851001_35_dialog_content = "¡Cuidado! ¡Encima de nosotros!!",
  ui_story_5085_50851001_36_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5085_50851001_37_dialog_content = "¡Las ruinas están empezando a temblar!",
  ui_story_5085_50851001_38_dialog_content = "Ah... ¡Ahhhhhhh—!",
  ui_story_5085_50851001_39_dialog_content = "¿Fleur?! ¿Qu-Qu-Qué te pasa?!",
  ui_story_5085_50851001_40_dialog_content = "¡Ah!",
  ui_story_5085_50851001_41_dialog_content = "¡Tenemos que salir de aquí! Si las ruinas están perdiendo el control, entonces Fleur es—",
  ui_story_5085_50851001_42_dialog_content = "Fleur... ¡Se está fusionando con la piedra y la maquinaria de las ruinas!",
  ui_story_5085_50851001_43_dialog_content = "¿Se está convirtiendo en un mecha?!",
  ui_story_5085_50851001_44_dialog_content = "¿Ah?",
  ui_story_5085_50851001_45_dialog_content = "¿Entonces son las ruinas las que hacen esto? ¿O podría ser que Fleur finalmente está resistiendo su control?",
  ui_story_5085_50851001_46_dialog_content = "¡No creo que eso sea nuestra mayor preocupación en este momento!",
  ui_story_5085_50851001_47_dialog_content = "¡Va a arrasar con todo este lugar si no lo detenemos pronto!!!",
  ui_story_5085_50851001_48_dialog_content = "El reino debe renacer... ¡Debo hacer realidad nuestro sueño!",
  ui_story_5085_50851001_49_dialog_content = "¡Hraaaaaah—!",
  ui_story_5085_50851002_1_dialog_content = "¡Está empezando a desmoronarse! ¡Ahora, Navegante!",
  ui_story_5085_50851002_2_dialog_content = "¡Entendido!",
  ui_story_5085_50851002_3_dialog_content = "<color=#e8d9bb>Ruido sordo-</color>",
  ui_story_5085_50851002_4_dialog_content = "¡Fleur! ¿Estás bien?!",
  ui_story_5085_50851002_5_dialog_content = "Mi mecha... Mi reino...",
  ui_story_5085_50851002_6_dialog_content = "Todavía no ha salido de eso... Simplemente lo sacaré de aquí... ¿Hmm?",
  ui_story_5085_50851002_7_dialog_content = "?!?",
  ui_story_5085_50851002_8_dialog_content = "Ustedes tres están brillando de repente...",
  ui_story_5085_50851002_9_dialog_content = "... ¡Justo como los tres emblemas!",
  ui_story_5085_50851002_10_dialog_content = "Ya veo... El príncipe quería que nos reuniéramos aquí desde el principio.",
  ui_story_5085_50851002_11_dialog_content = "Y ahora que su conciencia se ha ido... Es hora de que los salvadores elegidos de su reino también regresen.",
  ui_story_5085_50851002_12_dialog_content = "Pero...",
  ui_story_5085_50851002_13_dialog_content = "¡Las ruinas... Y toda esta montaña! ¡Están a punto de derrumbarse todas!",
  ui_story_5085_50851002_14_dialog_content = "No es solo la montaña... ¡Toda la isla está temblando! ¿Qué deberíamos hacer...?",
  ui_story_5085_50851002_15_dialog_content = "Dirígete a la playa. Tu amigo te está esperando allí.",
  ui_story_5085_50851002_16_dialog_content = "Fleur? No espera... Eres el príncipe, ¿no es así? ¿Qué quieres decir con \"nuestro amigo\"?",
  ui_story_5085_50851002_17_dialog_content = "¡Él tiene razón, sabes! Al menos estaremos a salvo de los escombros que caen en la playa, ¡así que apresurémonos!",
  ui_story_5085_50851002_18_dialog_content = "Entonces, parece que nuestra misión final...",
  ui_story_5085_50851002_19_dialog_content = "¡Es para escoltar a todos de manera segura a la playa antes de que volvamos a nuestro propio mundo! ¡Todavía hay tiempo!",
  ui_story_5085_50851002_20_dialog_content = "¡Correcto! ¡Apresurémonos!",
  ui_story_5085_50851002_21_dialog_content = "Ustedes...",
  ui_story_5085_50851002_22_dialog_content = "¡Solo espero que tengamos la oportunidad de despedirnos una vez que lleguemos allí!",
  ui_story_5085_50851100_1_dialog_content = "¡Oye—por aquí—",
  ui_story_5085_50851100_2_dialog_content = "¡Sr. Corax—!",
  ui_story_5085_50851100_3_dialog_content = "(Así que el amigo que mencionó era Corax, ¿eh?)",
  ui_story_5085_50851100_4_dialog_content = "¿Están todos a salvo? El barco de rescate llegará a tierra pronto, así que por favor aguanten un poco más.",
  ui_story_5085_50851100_5_dialog_content = "Uf... Finalmente llegamos al barco. No estamos olvidando a nadie esta vez, ¿verdad?",
  ui_story_5085_50851100_6_dialog_content = "No veo a Ryza por ninguna parte... ¡Ryza! ¿Dónde estás?!",
  ui_story_5085_50851100_7_dialog_content = "¡Soy... Estoy aquí!",
  ui_story_5085_50851100_8_dialog_content = "Lo siento si hice que alguien se preocupara.",
  ui_story_5085_50851100_9_dialog_content = "Si todos están aquí ahora, iré a informar al Sr. Corax que estamos listos para zarpar.",
  ui_story_5085_50851100_10_dialog_content = "La isla... Al final, se hundió en el mar...",
  ui_story_5085_50851100_11_dialog_content = "Sí, y sin dejar rastro de su existencia.",
  ui_story_5085_50851100_12_dialog_content = "Ahí va mi dinero para mantener el Colossus...",
  ui_story_5085_50851100_13_dialog_content = "Jejeje, yo no estaría tan seguro! Echen un vistazo a esto, todos—",
  ui_story_5085_50851100_14_dialog_content = "¿Son estos... los fragmentos del trono del rey? ¿Es por esto que tardaste tanto en volver, Ryza?!",
  ui_story_5085_50851100_15_dialog_content = "¡Sí! Aunque era peligroso, seguiste usando tus poderes para buscar la verdad... Así que naturalmente tuve que ayudar a mi manera también!",
  ui_story_5085_50851100_17_dialog_content = "Ryza...",
  ui_story_5085_50851100_18_dialog_content = "Ella realmente se superó a sí misma esta vez...",
  ui_story_5085_50851100_19_dialog_content = "Veamos qué nos pueden decir los últimos fragmentos restantes de esas ruinas—",
  ui_story_5085_50851100_20_dialog_content = "A Su Alteza Real el Príncipe,",
  ui_story_5085_50851100_21_dialog_content = "Los Eclipsites se han vuelto aún más salvajes, y el poder de las ruinas ha comenzado a decaer. Me temo que nuestro reino insular no resistirá mucho más tiempo.",
  ui_story_5085_50851100_22_dialog_content = "Y así, hemos decidido seguir tus nobles pasos y guiar a nuestra gente hacia el continente en busca de un nuevo hogar.",
  ui_story_5085_50851100_23_dialog_content = "Es posible que no podamos cantar tus alabanzas a tu regreso triunfal...",
  ui_story_5085_50851100_24_dialog_content = "Pero ten la seguridad de que tu pueblo no ha sido vencido. Simplemente han elegido comenzar de nuevo en una tierra extranjera.",
  ui_story_5085_50851100_25_dialog_content = "May crucemos caminos y nos reunamos nuevamente en el brillante y próspero continente.",
  ui_story_5085_50851100_26_dialog_content = "¡Así que el reino nunca fue aniquilado en primer lugar!",
  ui_story_5085_50851100_27_dialog_content = "¡Viajaron al continente de Astra y encontraron nuevas vidas allí!",
  ui_story_5085_50851100_28_dialog_content = "Aunque el príncipe nunca regresó de su aventura, sus acciones allanaron el camino para la supervivencia de su pueblo...",
  ui_story_5085_50851100_29_dialog_content = "¡Eso no solo lo hace un príncipe digno, sino también un valiente aventurero!",
  ui_story_5085_50851100_30_dialog_content = "Si sus descendientes supieran todo esto... ¿Intentarían reunirse en el continente?",
  ui_story_5085_50851100_32_dialog_content = "No importa cuánto tiempo pase, sus corazones siempre estarán unidos. De hecho, estoy seguro de que ya se reunieron en algún lugar.",
  ui_story_5085_50851100_33_dialog_content = "¡También lo creo! ¡Puedo sentir el ardiente amor que une sus corazones!",
  ui_story_5085_50851100_34_dialog_content = "Puede que no sea el final perfecto para su historia...",
  ui_story_5085_50851100_35_dialog_content = "Pero sigue siendo bueno... Y eso debería ser más que suficiente.",
  ui_story_5085_50851100_36_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5085_50851100_37_dialog_content = "...",
  ui_story_5085_50851100_38_dialog_content = "Oh... Parece que es hora de que nos despidamos ahora.",
  ui_story_5085_50851100_39_dialog_content = "Si alguna vez tenemos la oportunidad de encontrarnos de nuevo, me encantaría escuchar todo sobre tus aventuras, PlayerName...",
  ui_story_5085_50851100_40_dialog_content = "Es una lástima que ni siquiera pueda usar la alquimia para hacer regalos de despedida para todos, pero...",
  ui_story_5085_50851100_41_dialog_content = "¡Siempre apreciaré nuestra aventura de hoy más que cualquier otro tesoro!",
  ui_story_5085_50851100_42_dialog_content = "¡Y-Yo también! ¡Ha sido un placer conocer a todos aquí! Y señorita Barbara, ¡no desearía nada más que ver uno de tus conciertos algún día!",
  ui_story_5085_50851100_43_dialog_content = "¿Oh? ¡Entonces me aseguraré de que recibas el mejor trato VIP imaginable!",
  ui_story_5085_50851100_44_dialog_content = "Aunque nuestro tiempo juntos fue corto... Nunca olvidaré a ninguno de ustedes.",
  ui_story_5085_50851100_45_dialog_content = "¡Zarya! Hagamos nuestro mejor esfuerzo y sigamos creciendo!",
  ui_story_5085_50851100_46_dialog_content = "¡Yo tampoco olvidaré, pero... Pero tampoco perderé contra ti, Patty!",
  ui_story_5085_50851100_47_dialog_content = "Sé que es hora de ir por caminos separados, pero simplemente no puedo decirlo en voz alta...",
  ui_story_5085_50851100_48_dialog_content = "¡No te veas tan triste, PlayerName! ¡Estoy seguro de que nos volveremos a encontrar algún día!",
  ui_story_5085_50851100_49_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5085_50851100_50_dialog_content = "Oh...",
  ui_story_5085_50851100_51_dialog_content = "¿T-Todavía estamos aquí?!",
  ui_story_5085_50851100_52_dialog_content = "¡P-Perdón por la interrupción, pero creo que puedo explicar!",
  ui_story_5085_50851100_53_dialog_content = "Fleur? Espera... ¿Todavía eres el príncipe, verdad?",
  ui_story_5085_50851100_54_dialog_content = "No, estoy bastante seguro de que todavía soy Fleur.",
  ui_story_5085_50851100_55_dialog_content = "\"¿Bastante seguro\"?!",
  ui_story_5085_50851100_56_dialog_content = "Eso es correcto, aunque tengo un mensaje para todos del príncipe...",
  ui_story_5085_50851100_57_dialog_content = "Gracias a tus esfuerzos, finalmente aprendió que su preciosa gente logró salir de la isla de manera segura, y comenzó nuevas vidas en el continente de Astra.",
  ui_story_5085_50851100_58_dialog_content = "Él también se disculpó sinceramente por causar tantos problemas a todos.",
  ui_story_5085_50851100_59_dialog_content = "Entonces, como muestra de buena voluntad, utilizó el último poder restante de las ruinas...",
  ui_story_5085_50851100_60_dialog_content = "¡Para mantener a los tres de ustedes en nuestro mundo por un poco más de tiempo!",
  ui_story_5085_50851100_61_dialog_content = "Desafortunadamente, las ruinas no tenían mucha energía restante en ellas, y pronto el efecto se desvanecerá.",
  ui_story_5085_50851100_62_dialog_content = "¡Pero al menos, podrás disfrutar de una agradable aventura de verano aquí en Astra!",
  ui_story_5085_50851100_63_dialog_content = "¡¿Eh?!",
  ui_story_5085_50851100_64_dialog_content = "Eso es genial y todo... Pero, ¿no crees que él debería disculparse contigo más que nada?",
  ui_story_5085_50851100_65_dialog_content = "Ah, no hay necesidad de preocuparse por eso. ¡Ya me impartió el conocimiento de ese mecha!",
  ui_story_5085_50851100_66_dialog_content = "Una vez que lleguemos a casa, podré hacer algo verdaderamente increíble.",
  ui_story_5085_50851100_67_dialog_content = "(¡Espera, eso significa que en realidad estaba molesto cuando lo destruimos antes!)",
  ui_story_5085_50851100_68_dialog_content = "De todos modos... Creo que estamos perdiendo el punto aquí...",
  ui_story_5085_50851100_69_dialog_content = "Entonces... ¿Esto significa que puedo quedarme en tu mundo un poco más?!",
  ui_story_5085_50851100_70_dialog_content = "¡En ese caso, quiero ver todo lo que este mundo tiene para ofrecer! El Colossus, el Desierto Rediesel, Lumopolis... ¿Puedes mostrarnos todo eso y más, verdad Navegador?!",
  ui_story_5085_50851100_71_dialog_content = "¡Por supuesto! Ahora son nuestros amigos cercanos, así como las personas que nos salvaron la vida antes.",
  ui_story_5085_50851100_72_dialog_content = "Como el Navegador del Colossus, sería un honor darles la bienvenida a bordo a los tres!",
  ui_story_5085_50851100_73_dialog_content = "¡Guau, muchas gracias! ¡No puedo esperar para embarcarme en todo tipo de aventuras en tu mundo!",
  ui_story_5085_50851100_74_dialog_content = "¡Divirtámonos tanto como podamos antes de que realmente sea hora de decir adiós!",
  ui_story_5085_50851100_76_dialog_content = "Cuento contigo para que me muestres este mundo, ¡Navegador! Bien, ¡vamos!",
  ui_story_5085_50851100_77_dialog_content = "Ryza, Navegante... May ¿Puedo unirme a ti también?",
  ui_story_5085_50851100_78_dialog_content = "¡No te olvides de mí!",
  ui_story_5085_50851100_79_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_5085_50851100_80_dialog_content = "<color=#e8d9bb>La isla yace silenciosamente en el fondo del mar, junto con las evidencias de su antigua gloria. Ahora, una nueva aventura de verano está a punto de comenzar.</color>",
  ui_story_5085_50851100_81_dialog_content = "Próxima parada: ¡Astra! ¡A toda vela adelante!"
}
return config
